const MAX_DUPLICATE_RESOLUTIONS=10000;
function normalizeDuplicateResolution(value){
 if(typeof value==='string')return value.trim();
 if(!value||typeof value!=='object'||Array.isArray(value))return '';
 if(typeof value.key==='string')return value.key.trim();
 if(typeof value.value==='string')return value.value.trim();
 const keys=Object.keys(value).filter(k=>/^\d+$/.test(k)).sort((a,b)=>Number(a)-Number(b));
 return keys.length?keys.map(k=>String(value[k]??'')).join('').trim():'';
}
function normalizeDuplicateResolutions(values){
 const seen=new Set(),result=[];
 (Array.isArray(values)?values:[]).forEach(value=>{const key=normalizeDuplicateResolution(value);if(key&&!seen.has(key)){seen.add(key);result.push(key)}});
 return result.length>MAX_DUPLICATE_RESOLUTIONS?result.slice(-MAX_DUPLICATE_RESOLUTIONS):result;
}

