function provinceFilterValue(value){const text=String(value??'').trim();return text?normalizeProvince(text):''}
function provinceFilterMatches(customerProvince,filterProvince){const filter=provinceFilterValue(filterProvince);return!filter||normalizeProvince(customerProvince)===filter}
function provinceNames(values=[]){return[...new Set((Array.isArray(values)?values:[]).map(normalizeProvince).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
