function provinceFilterOptions(values=[],selected='',includeEmpty=false){const current=provinceFilterValue(selected),emptySelected=selected==='__empty__',names=provinceNames(values),national=names.includes(ALL_PROVINCE)?`<option value="${ALL_PROVINCE}" ${current===ALL_PROVINCE?'selected':''}>${ALL_PROVINCE}</option>`:'',otherProvinces=names.filter(province=>province!==ALL_PROVINCE).map(province=>`<option value="${attr(province)}" ${current===province?'selected':''}>${esc(province)}</option>`).join('');return`<option value="" ${!current&&!emptySelected?'selected':''}>全部省份</option>${national}${includeEmpty?`<option value="__empty__" ${emptySelected?'selected':''}>未设置省份</option>`:''}${otherProvinces}`}
