const PHONE_NUMBER_RE=/(?<!\d)1[3-9]\d{9}(?!\d)/g;
function extractPhoneNumbers(value){const text=String(value??'');const found=text.match(PHONE_NUMBER_RE)||[];return [...new Set(found)];}
function normalizePhone(v){return extractPhoneNumbers(v).join('\n')}
function splitPhoneValues(value){return String(value??'').trim().split(PHONE_VALUE_SEPARATOR_RE).map(x=>x.trim()).filter(Boolean)}
function isValidPhone(v){const text=String(v??'').trim();if(!text)return true;const numbers=extractPhoneNumbers(text);if(!numbers.length)return false;let remainder=text.replace(PHONE_NUMBER_RE,'').replace(PHONE_VALUE_SEPARATOR_RE,'');return !remainder&&splitPhoneValues(text).every(item=>/^1[3-9]\d{9}$/.test(item))}
function formatCustomerPhoneInput(value){return String(value??'').replace(/\r?\n/g,'；')}
function isValidCustomerPhoneInput(value){const text=String(value??'').trim();if(!text)return true;const values=text.split(/[；;]/).map(item=>item.trim()).filter(Boolean);return values.length>0&&values.every(item=>/^1[3-9]\d{9}$/.test(item))}
function normalizeCustomerPhoneInput(value){return String(value??'').trim().split(/[；;]/).map(item=>item.trim()).filter(Boolean).join('\n')}
function normalizeDouyinProfileUrl(value){const text=String(value??'').trim();if(!text)return'';try{const url=new URL(text);if(!['http:','https:'].includes(url.protocol))return'';return url.href}catch{return''}}
function validateCustomerPhoneField(field,notify=false){if(!field)return true;const valid=isValidCustomerPhoneInput(field.value);field.setCustomValidity(valid?'':'手机号格式不正确，请填写 11 位手机号，多个手机号以；分隔');field.classList.toggle('zx-customer-phone-invalid',!valid);const hint=field.closest('.zx-field')?.querySelector('[data-customer-phone-hint]');if(hint){hint.textContent=valid?'填多个手机号以；分隔':'手机号格式不正确，请检查后再保存';hint.classList.toggle('is-error',!valid)}if(!valid&&notify)toast('手机号格式不正确，请填写 11 位手机号，多个手机号以；分隔','error');return valid}

const QR_CODE_MAX_BYTES=10*1024*1024;
const QR_CODE_TYPES=new Set(['image/png','image/jpeg','image/webp']);
function normalizeQrCodes(value){const list=Array.isArray(value)?value:[];return list.map((item,index)=>{if(typeof item==='string'){if(item.startsWith('data:image/'))return{id:uid('qr'),name:'二维码图片',type:'image/png',size:0,dataUrl:item,createdAt:now()};const text=item.trim();return text?{id:uid('qr'),name:'导入二维码文本',type:'text/plain',size:0,text,createdAt:now()}:null}if(!item||typeof item!=='object')return null;const dataUrl=String(item.dataUrl||item.data_url||'');if(dataUrl.startsWith('data:image/'))return{id:String(item.id||uid('qr')),name:String(item.name||item.fileName||'二维码图片'),type:String(item.type||item.mimeType||'image/png'),size:Number(item.size)||0,dataUrl,createdAt:item.createdAt||item.created_at||now()};const text=String(item.text||item.value||item.url||'').trim();return text?{id:String(item.id||uid('qr')),name:String(item.name||'导入二维码文本'),type:'text/plain',size:0,text,createdAt:item.createdAt||item.created_at||now()}:null}).filter(Boolean).slice(0,50)}
function customerQrCodes(customer){return normalizeQrCodes(customer?.qrCodes??customer?.qr_codes??customer?.wechatQrCodes??customer?.wechat_qr_codes)}
function qrCodeListMarkup(list,editable=true){return (normalizeQrCodes(list)||[]).map(item=>`<div class="zx-qr-item" data-qr-item="${attr(item.id)}">${item.dataUrl?`<button type="button" class="zx-qr-preview-button" data-qr-view="${attr(item.id)}" title="点击放大查看"><img src="${attr(item.dataUrl)}" alt="${attr(item.name||'微信加好友二维码')}"></button>`:`<div class="zx-qr-text-preview" title="${attr(item.text||'')}">${esc(item.text||'')}</div>`}<div class="zx-qr-item-meta"><span title="${attr(item.name)}">${esc(item.name||'二维码图片')}</span>${item.size?`<small>${(item.size/1024/1024).toFixed(2)} MB</small>`:''}</div>${editable?`<div class="zx-qr-item-actions"><button type="button" class="zx-btn small" data-action="qr-replace" data-qr-id="${attr(item.id)}">替换</button><button type="button" class="zx-btn danger small" data-action="qr-delete" data-qr-id="${attr(item.id)}">删除</button><input type="file" accept="image/png,image/jpeg,image/webp" data-qr-replace-input="${attr(item.id)}" hidden></div>`:''}</div>`).join('')}
function qrInlinePreviewMarkup(list){const items=normalizeQrCodes(list);if(!items.length)return '<div class="zx-qr-dropzone-empty"><span class="zx-qr-dropzone-icon">＋</span><strong>添加二维码</strong></div>';return '<div class="zx-qr-inline-previews" data-qr-inline-previews>'+items.map(item=>item.dataUrl?'<button type="button" class="zx-qr-inline-preview" data-qr-view="'+attr(item.id)+'" title="点击放大查看"><img src="'+attr(item.dataUrl)+'" alt="'+attr(item.name||'微信加好友二维码')+'"></button>':'<span class="zx-qr-inline-text" title="'+attr(item.text||'')+'">'+esc(item.text||'二维码文本')+'</span>').join('')+'</div><span class="zx-qr-inline-count">'+items.length+'项</span>'}
function renderCustomerQrEditor(customer){if(!modalState)modalState={};modalState.qrCodes=normalizeQrCodes(customerQrCodes(customer));return `<div class="zx-field zx-qr-field"><label>微信加好友二维码</label><div class="zx-qr-dropzone" data-qr-dropzone tabindex="0"><input type="file" accept="image/png,image/jpeg,image/webp" multiple data-qr-input hidden><div class="zx-qr-dropzone-content" data-qr-dropzone-content>${qrInlinePreviewMarkup(modalState.qrCodes)}</div><button type="button" class="zx-btn small" data-action="qr-select">${modalState.qrCodes.length?'继续添加':'选择图片'}</button></div><div class="zx-qr-list" data-qr-list>${qrCodeListMarkup(modalState.qrCodes,true)||''}</div></div>`}
function renderCustomerQrGallery(customer){const list=customerQrCodes(customer);if(!list.length)return '';return `<section class="zx-info zx-qr-gallery"><div class="zx-qr-gallery-head"><strong>微信加好友二维码</strong><span>${list.length} 张</span></div><div class="zx-qr-list">${qrCodeListMarkup(list,false)}</div></section>`}
const CUSTOMER_BASIC_COPYABLE=new Set(['姓名','手机号','抖音昵称','微信昵称','微信号','抖音号','公众号','视频号','机构名称','地址','备注']);
function customerBasicFieldCopyValue(label,value){
 const text=String(value??'').trim();
 if(!text)return'';
 return label==='手机号'?splitPhoneValues(text).join('；'):text;
}
function customerBasicLabelMarkup(label,value){
 const copyValue=customerBasicFieldCopyValue(label,value);
 const copyButton=CUSTOMER_BASIC_COPYABLE.has(label)&&copyValue?`<button type="button" class="zx-btn small zx-basic-icon-btn zx-copy-button zx-field-copy-button" data-copy-value="${attr(copyValue)}" data-copy-label="${attr(label)}" aria-label="复制${esc(label)}" title="复制${esc(label)}"><span aria-hidden="true">⧉</span></button>`:'';
 return `<label>${label}${copyButton}</label>`;
}
function customerBasicCopyMarkup(label,value){
 const text=String(value??'').trim();
 if(!text)return '-';
 if(label==='手机号'){
  const phones=splitPhoneValues(text);
  if(phones.length)return phones.map((phone,index)=>`${index?'<span class="zx-phone-separator" aria-hidden="true">；</span>':''}<button type="button" class="zx-copyable zx-phone-copy" data-copy-value="${attr(phone)}" data-copy-label="手机号" title="点击复制手机号">${esc(phone)}</button>`).join('');
 }
 if(CUSTOMER_BASIC_COPYABLE.has(label))return `<span class="zx-copyable" data-copy-value="${attr(text)}" data-copy-label="${attr(label)}" title="点击复制${esc(label)}">${esc(text)}</span>`;
 return esc(text);
}
function customerDouyinMarkup(customer){
 const text=String(customer?.douyin_id??'').trim();
 const profileUrl=normalizeDouyinProfileUrl(customer?.douyin_profile_url);
 if(!text&&!profileUrl)return '-';
 const search=text?`<a class="zx-douyin-link" href="https://www.douyin.com/search/${encodeURIComponent(text)}?type=user" target="_blank" rel="noopener noreferrer" title="搜索抖音号">${esc(text)}<span aria-hidden="true">↗</span></a>`:'';
 const profile=profileUrl?`<a class="zx-btn primary small zx-basic-icon-btn zx-douyin-profile-button" href="${attr(profileUrl)}" target="_blank" rel="noopener noreferrer" aria-label="打开抖音主页" title="打开抖音主页">抖音主页</a>`:'';
 return `<span class="zx-douyin-actions">${search}${profile}</span>`;
}
function customerBasicInfoMarkup(customer,{includePriority=true}={}){
 const c=customer||{};
 const infoFields=[
  ['姓名',c.name],['销售状态',c.sales_status],['省份',c.province],['城市',c.city],
  ['手机号',c.phone],['抖音昵称',c.douyin_nickname],['抖音号',c.douyin_id],['抖音粉丝量',c.douyin_followers],
  ['微信昵称',c.wechat_nickname],['微信号',c.wechat_id],['管理的微信账户',managedWechatAccountLabel(c)],['朋友圈客单',c.moments_orders],
  ['公众号',c.official_account],['视频号',c.channel_account],['机构名称',c.org_name],['客户身份',c.identity],
  ['QQ号',c.qq],['地址',c.address],['备注',c.remark]
 ];
 if(includePriority)infoFields.push(['优先对接评分',customerPrioritySummary(c)]);
 const fields=infoFields.map(([label,value])=>{
  const content=label==='抖音号'?customerDouyinMarkup(c):label==='优先对接评分'?value:customerBasicCopyMarkup(label,value);
  return `<div class="zx-info zx-basic-info ${label==='优先对接评分'?'zx-basic-priority-info':''} ${label==='备注'?'zx-basic-remark-info':''}" ${label==='管理的微信账户'?'data-managed-wechat-account-info="1"':''}>${customerBasicLabelMarkup(label,value)}<div>${content}</div></div>`;
 }).join('');
 return `<div class="zx-info-grid zx-customer-basic-info-grid">${fields}</div>${renderCustomerQrGallery(c)}`;
}
function refreshQrEditor(){const qrCodes=normalizeQrCodes(modalState?.qrCodes||[]);const list=$('[data-qr-list]');if(list)list.innerHTML=qrCodeListMarkup(qrCodes,true)||'';const content=$('[data-qr-dropzone-content]');if(content)content.innerHTML=qrInlinePreviewMarkup(qrCodes);const button=$('[data-action=qr-select]');if(button)button.textContent=qrCodes.length?'继续添加':'选择图片'}
function showQrViewer(item){if(!item)return;if(!item.dataUrl)return navigator.clipboard?.writeText(item.text||'').then(()=>toast('二维码文本已复制','success'));document.getElementById('zxQrViewer')?.remove();const el=document.createElement('div');el.id='zxQrViewer';el.className='zx-qr-viewer';el.innerHTML=`<button type="button" class="zx-qr-viewer-close" data-action="qr-close-viewer" aria-label="关闭">×</button><img src="${attr(item.dataUrl)}" alt="${attr(item.name||'微信加好友二维码')}">`;el.addEventListener('click',e=>{if(e.target===el)el.remove()});document.body.appendChild(el)}
function qrFileError(message){toast(message,'error')}
function readQrFile(file){return new Promise((resolve,reject)=>{if(!file)return reject(new Error('文件为空'));if(!QR_CODE_TYPES.has(String(file.type||'').toLowerCase()))return reject(new Error('仅支持 PNG、JPG、JPEG、WEBP 图片'));if(file.size>QR_CODE_MAX_BYTES)return reject(new Error('单张二维码图片不能超过 10MB'));const reader=new FileReader();reader.onload=()=>resolve({id:uid('qr'),name:file.name||'二维码图片',type:file.type||'image/png',size:file.size,dataUrl:String(reader.result||''),createdAt:now()});reader.onerror=()=>reject(new Error('图片读取失败，请重新选择'));reader.readAsDataURL(file)})}
async function appendQrFiles(files,replaceId=''){if(!modalState||!['customer','dedupe-capture'].includes(modalState.type))return;const incoming=Array.from(files||[]).filter(Boolean);if(!incoming.length)return;const added=[];for(const file of incoming){try{added.push(await readQrFile(file))}catch(error){qrFileError(`${file.name||'图片'}：${error.message}`)}}if(!added.length)return;const existing=normalizeQrCodes(modalState.qrCodes);if(replaceId){const index=existing.findIndex(item=>String(item.id)===String(replaceId));if(index>=0)existing.splice(index,1,added[0]);else existing.push(added[0]);if(added.length>1)existing.push(...added.slice(1))}else existing.push(...added);modalState.qrCodes=existing.slice(0,50);refreshQrEditor();toast(replaceId?'二维码已替换':'二维码已添加，请点击保存后正式保存','success')}
function qrInputFor(id){return id?document.querySelector(`[data-qr-replace-input="${CSS.escape(String(id))}"]`):$('[data-qr-input]')}

function isImportCommunicationStatus(value){return IMPORT_COMMUNICATION_STATUS_RE.test(importCellText(value))}
function isImportContactPlaceholder(value){return IMPORT_CONTACT_PLACEHOLDER_VALUES.has(importCellText(value).replace(/[。.!！]+$/g,'').trim())}
function normalizeImportedWechatIds(value){return[...new Set(importCellText(value).split(PHONE_VALUE_SEPARATOR_RE).map(item=>item.replace(/^(?:微信号|微信|号)\s*[：:：]?\s*/i,'').trim()).filter(item=>item&&!isImportContactPlaceholder(item)))].join('\n')}
function splitImportContact(value){const text=String(value??'').trim();if(!text)return{phones:[],wechatIds:[],communicationNotes:[]};const phones=extractPhoneNumbers(text);let rest=text;phones.forEach(phone=>{rest=rest.replace(phone,'')});const wechatIds=[],communicationNotes=[];rest.split(PHONE_VALUE_SEPARATOR_RE).map(item=>item.replace(/^(?:联系方式|联系方法|手机号|手机|电话|微信号|微信|号)\s*[：:：]?\s*/i,'').trim()).filter(item=>item&&!isImportContactPlaceholder(item)).forEach(item=>{if(isImportCommunicationStatus(item))communicationNotes.push(item);else wechatIds.push(item)});return{phones:[...new Set(phones)],wechatIds:[...new Set(wechatIds)],communicationNotes:[...new Set(communicationNotes)]}}
function mergePhoneValues(existing,value){return [...new Set([...extractPhoneNumbers(existing),...extractPhoneNumbers(value)])].join('\n')}

const cityOptions=province=>PROVINCE_CITIES[normalizeProvince(province)]||[];
function mapFeatureName(f){return normalizeProvince(f?.properties?.name||'');}
function geoBounds(features){let b=[Infinity,Infinity,-Infinity,-Infinity];const walk=x=>{if(!Array.isArray(x))return;if(typeof x[0]==='number'){b[0]=Math.min(b[0],x[0]);b[1]=Math.min(b[1],x[1]);b[2]=Math.max(b[2],x[0]);b[3]=Math.max(b[3],x[1]);return}x.forEach(walk)};features.forEach(f=>walk(f.geometry?.coordinates));return b[0]===Infinity?[73,18,135,54]:b;}
function geoPath(geometry,b,w=960,h=420){const sx=(w-20)/(b[2]-b[0]),sy=(h-20)/(b[3]-b[1]),scale=Math.min(sx,sy),ox=(w-(b[2]-b[0])*scale)/2,oy=(h-(b[3]-b[1])*scale)/2;const ring=r=>r.map((p,i)=>`${i?'L':'M'}${(p[0]-b[0])*scale+ox},${h-((p[1]-b[1])*scale+oy)}`).join(' ')+' Z';const draw=x=>Array.isArray(x)&&typeof x[0]?.[0]==='number'?ring(x):x.map(draw).join(' ');return draw(geometry.coordinates);}
const PROVINCE_MAP_LABEL_OFFSETS={北京:[-10,-8],天津:[12,7],河北:[8,7],山西:[-8,3],辽宁:[5,5],上海:[16,3],江苏:[0,-8],浙江:[12,8],安徽:[-8,0],福建:[9,7],江西:[-8,7],山东:[7,-4],河南:[-6,0],湖北:[4,-4],湖南:[-5,5],广东:[-8,-3],广西:[-8,4],海南:[0,8],重庆:[8,-5],四川:[-6,0],贵州:[5,6],云南:[-5,3],陕西:[8,7],甘肃:[-8,4],宁夏:[5,-8],台湾:[12,2],香港:[21,6],澳门:[18,17]};
function geoPoint(point,b,w=960,h=420){const sx=(w-20)/(b[2]-b[0]),sy=(h-20)/(b[3]-b[1]),scale=Math.min(sx,sy),ox=(w-(b[2]-b[0])*scale)/2,oy=(h-(b[3]-b[1])*scale)/2;return [(point[0]-b[0])*scale+ox,h-((point[1]-b[1])*scale+oy)];}
function provinceMapLabel(feature,bounds){const province=mapFeatureName(feature),point=feature?.properties?.centroid||feature?.properties?.center;if(!province||!Array.isArray(point)||!Number.isFinite(point[0])||!Number.isFinite(point[1]))return '';const [x,y]=geoPoint(point,bounds),[dx,dy]=PROVINCE_MAP_LABEL_OFFSETS[province]||[0,0];return `<text class="zx-map-label" x="${(x+dx).toFixed(1)}" y="${(y+dy).toFixed(1)}" text-anchor="middle" dominant-baseline="central">${esc(province)}</text>`;}
function pendingCustomers(){return state.customers.filter(c=>c.approval==='待确认')}
function customerRecentTime(customer){return Date.parse(customer?.updatedAt||customer?.updated_at||customer?.createdAt||customer?.created_at||0)||0}
function provinceCounts(customers=officialCustomers()){const out={};customers.forEach(c=>{const p=normalizeProvince(c.province)||'未设置';out[p]=(out[p]||0)+1});return out;}
function provinceMapColor(count,max){if(!count)return '#e8eefb';const ratio=Math.max(0,Math.min(1,Math.pow(count/Math.max(1,max),.62)));const lightness=94-ratio*48;return `hsl(221 88% ${lightness}%)`;}
function provinceRankingProvince(customer){return normalizeProvince(customer?.province)||'未设置省份'}
function provinceRankingStatusNames(){return [...new Set([...(state.statuses||[]).map(status=>String(status?.name||'').trim()),...officialCustomers().map(customer=>String(customer?.sales_status||'').trim())].filter(Boolean))]}
function provinceRankingRows(mode,status){
 const groups=new Map();
 officialCustomers().forEach(customer=>{
  const province=provinceRankingProvince(customer),group=groups.get(province)||{province,total:0,phone:0,wechat:0,contact:0,status:0};
  group.total++;
  if(contactValuePresent(customer.phone))group.phone++;
  if(contactValuePresent(customer.wechat_id))group.wechat++;
  if(contactValuePresent(customer.phone)||contactValuePresent(customer.wechat_id))group.contact++;
  if(mode==='status'&&String(customer.sales_status||'').trim()===status)group.status++;
  groups.set(province,group);
 });
 const metric=mode==='total'?'total':mode==='contact'?'contact':'status';
 const rows=[...groups.values()].filter(row=>row[metric]>0).sort((left,right)=>right[metric]-left[metric]||left.province.localeCompare(right.province,'zh-CN'));
 let previousCount=null,previousRank=0;
 return rows.map((row,index)=>{const count=row[metric];if(count!==previousCount)previousRank=index+1;previousCount=count;return{...row,count,rank:previousRank}});
}
function renderProvinceRankingRows(mode,status){
 const rows=provinceRankingRows(mode,status),metricLabel=mode==='total'?'正式客户':mode==='contact'?'有联系方式客户':status||'销售状态客户';
 if(!rows.length)return `<div class="zx-empty"><strong>暂无符合条件的省份数据</strong>当前排名条件下没有正式客户。</div>`;
 return `<div class="zx-province-ranking-list">${rows.map((row,index)=>`<div class="zx-province-ranking-row ${index<3?'is-top':''}"><span class="zx-province-ranking-rank">${row.rank}</span><div class="zx-province-ranking-main"><strong>${esc(row.province)}</strong>${mode==='contact'?`<small>联系方式 ${row.contact} 位 · 手机号 ${row.phone} 位 · 微信号 ${row.wechat} 位</small>`:`<small>${esc(metricLabel)} ${row.count} 位</small>`}</div><b>${row.count} 位</b></div>`).join('')}</div>`;
}
function renderProvinceRankingsModal(){
 const mode=modalState?.rankingMode||'total',statusNames=provinceRankingStatusNames();
 if(!statusNames.includes(modalState?.rankingStatus))modalState.rankingStatus=statusNames[0]||'';
 const statusSelect=`<label class="zx-province-ranking-status-select" ${mode==='status'?'':'hidden'}><span>销售状态</span><select class="zx-select" data-action="province-ranking-status" ${statusNames.length?'':'disabled'}>${statusNames.map(status=>`<option value="${attr(status)}" ${status===modalState.rankingStatus?'selected':''}>${esc(status)}</option>`).join('')}</select></label>`;
 const modes=[['total','客户总人数'],['contact','已有联系方式'],['status','销售状态']];
 const body=`<div class="zx-province-ranking-modal"><div class="zx-province-ranking-controls" role="tablist" aria-label="省份排名方式">${modes.map(([key,label])=>`<button type="button" class="zx-btn small ${mode===key?'primary':'ghost'}" data-action="province-ranking-mode" data-ranking-mode="${key}" aria-selected="${mode===key}">${label}</button>`).join('')}${statusSelect}</div><p class="zx-province-ranking-note">仅统计客户库正式客户；未填写省份归入“未设置省份”，人数为 0 的省份不展示。</p>${renderProvinceRankingRows(mode,modalState.rankingStatus)}</div>`;
 modal('各省份排名',body,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true,true,'zx-province-ranking-modal');
}
function showProvinceRankings(){modalState={type:'province-rankings',rankingMode:'total',rankingStatus:''};renderProvinceRankingsModal()}
function loadMap(){if(mapData||window.__zxMapLoading)return;if(window.__zxMapLoading=true,typeof fetch==='function')fetch('./china.json').then(r=>r.json()).then(d=>{mapData=d;window.__zxMapLoading=false;if(route()==='customers')render()}).catch(()=>{window.__zxMapLoading=false});}

const currentUser=()=>window.ZhiXunAuth?.getUser?.()||{username:'demo',display_name:'演示管理员'};
// 兼容本地数据和团队接口返回的创建人字段，仅用于展示/筛选，不改写客户数据。
const customerCreatorId=(customer)=>[customer?.userId,customer?.user_id,customer?.created_by_user_id,customer?.createdByUserId].map(value=>String(value??'').trim()).find(Boolean)||'';
// 今日新增客户按最近一次“加入客户库”操作人归属。旧数据没有该字段时，
// 回退到创建人，保证历史数据仍能正常展示。
const customerLibraryOperatorId=(customer)=>[
 customer?.joinedByUserId,customer?.joined_by_user_id,
 customer?.libraryJoinedByUserId,customer?.library_joined_by_user_id,
 customerCreatorId(customer)
].map(value=>String(value??'').trim()).find(Boolean)||'';
const customerLibraryOperatorName=(customer)=>[
 customer?.joinedBy,customer?.joinedByUsername,
 customer?.joined_by_name,customer?.joined_by_username,
 customer?.libraryJoinedBy,customer?.library_joined_by,
 customer?.createdBy,customer?.created_by_name,customer?.created_by,customer?.created_by_username
].map(value=>String(value??'').trim()).find(Boolean)||'';
function customerBelongsToCurrentUser(customer){const user=currentUser(),ownerId=customerCreatorId(customer),userId=String(user.id??'').trim();if(ownerId&&userId)return ownerId===userId;const ownerNames=[customer?.created_by_username,customer?.createdBy,customer?.created_by_name,customer?.created_by].map(value=>String(value??'').trim()).filter(Boolean),userNames=[user.username,user.display_name].map(value=>String(value??'').trim()).filter(Boolean);if(ownerNames.length&&userNames.length)return ownerNames.some(name=>userNames.includes(name));return !window.ZhiXunAuth?.isAuthenticated?.()&&!ownerId}
function todayNewBelongsToCurrentUser(customer){const user=currentUser(),userId=String(user.id??'').trim(),operatorId=customerLibraryOperatorId(customer);if(operatorId&&userId)return operatorId===userId;const operatorName=customerLibraryOperatorName(customer),names=[user.username,user.display_name].map(value=>String(value??'').trim()).filter(Boolean);if(operatorName&&names.length)return names.includes(operatorName);return !window.ZhiXunAuth?.isAuthenticated?.()&&!operatorId}
const userNames=()=>{const map={};const cu=currentUser();if(cu?.id!=null)map[String(cu.id)]=cu.display_name||cu.username||'当前用户';(state.customers||[]).forEach(item=>{const uid=customerLibraryOperatorId(item),name=customerLibraryOperatorName(item);if(uid&&name&&!map[uid])map[uid]=name});(state.tasks||[]).forEach(item=>{const uid=customerCreatorId(item),name=item.createdBy||item.created_by_name||item.created_by||item.created_by_username||'';if(uid&&name&&!map[uid])map[uid]=name});return map};
const userName=(uid)=>{const id=String(uid||'');if(!id)return'未知成员';const names=userNames();return names[id]||('成员 #'+id.slice(0,6))};
function userAvatarMarkup(uid,name){const id=String(uid??'').trim(),user=currentUser(),currentId=String(user.id??'').trim(),avatar=id&&id===currentId?String(user.avatar_url||'').trim():'';return avatar?`<img src="${attr(avatar)}" alt="${attr(name||'用户')}头像">`:esc((name||'?').slice(0,1))}
