function donutData(){const counts=new Map((state.statuses||[]).filter(status=>status&&status.name).map(status=>[status.name,0]));officialCustomers().forEach(c=>{const name=c.sales_status||'未设置';counts.set(name,(counts.get(name)||0)+1)});return Array.from(counts.entries()).sort((a,b)=>b[1]-a[1])}
