function loadGreeting(){try{var data=JSON.parse(localStorage.getItem("zhixun_one_stop_v1")||"{}");return (data.settings&&data.settings.greeting)||("欢迎回来，"+(currentUser().display_name||currentUser().username||"管理员"))}catch(e){return "欢迎回来，"+(currentUser().display_name||currentUser().username||"管理员")}}
function todayHistoryDateKey(date){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function todayHistoryDates(range=todayHistoryRange){const end=new Date();end.setHours(12,0,0,0);end.setDate(end.getDate()-1);let start=new Date(end);if(range==='all'){const earliest=officialCustomers().map(c=>localDate(officialJoinedAt(c))).filter(date=>date&&date<today()).sort()[0];start=earliest?new Date(earliest+'T12:00:00'):new Date(end);if(!earliest)start.setDate(start.getDate()-29)}else start.setDate(start.getDate()-(Math.max(1,Number(range)||30)-1));const dates=[];for(let cursor=new Date(start);cursor<=end;cursor.setDate(cursor.getDate()+1))dates.push(todayHistoryDateKey(cursor));return dates}
function todayHistoryGroups(dates){const dateSet=new Set(dates),groups=new Map(),todayKey=today(),scope=modalStack[modalStack.length-1]?.parentState?.type==='historical-records'?historicalStatusScope:todayNewFilter;officialCustomers().forEach(c=>{const date=localDate(officialJoinedAt(c));if(!date||date>todayKey||(scope==='mine'&&!todayNewBelongsToCurrentUser(c)))return;const operatorId=customerLibraryOperatorId(c),operatorName=customerLibraryOperatorName(c),key=operatorId||('legacy:'+(operatorName||'unknown'));if(!groups.has(key))groups.set(key,{key,uid:operatorId,name:operatorId?userName(operatorId):(operatorName||'未知成员'),allTotal:0,todayTotal:0,counts:new Map()});const group=groups.get(key);if(date===todayKey){group.todayTotal++;return}group.allTotal++;if(dateSet.has(date))group.counts.set(date,(group.counts.get(date)||0)+1)});return [...groups.values()].sort((a,b)=>{const at=dates.reduce((sum,date)=>sum+(a.counts.get(date)||0),0),bt=dates.reduce((sum,date)=>sum+(b.counts.get(date)||0),0);return bt-at||b.allTotal-a.allTotal||b.todayTotal-a.todayTotal||a.name.localeCompare(b.name,'zh-CN')})}
function todayHistoryRangeLabel(){return todayHistoryRange==='all'?'全部往期':`近 ${todayHistoryRange} 天`}
function todayHistoryChart(group,dates,index){const colors=['#315efb','#8b5cf6','#0891b2','#19a974','#f59e0b','#ec4899','#ef4444','#6366f1'],color=colors[index%colors.length],values=dates.map(date=>group.counts.get(date)||0),total=values.reduce((sum,value)=>sum+value,0),peak=Math.max(0,...values),average=dates.length?total/dates.length:0,w=760,h=210,left=42,right=18,top=18,bottom=34,plotW=w-left-right,plotH=h-top-bottom,max=Math.max(1,peak),x=i=>left+(dates.length<=1?plotW/2:i*plotW/(dates.length-1)),y=value=>top+plotH-value/max*plotH,points=values.map((value,i)=>`${x(i).toFixed(1)},${y(value).toFixed(1)}`).join(' '),area=values.length?`M ${x(0).toFixed(1)} ${(top+plotH).toFixed(1)} L ${points.replaceAll(' ',' L ')} L ${x(values.length-1).toFixed(1)} ${(top+plotH).toFixed(1)} Z`:'';const grid=[0,.25,.5,.75,1].map(ratio=>{const value=Math.round(max*(1-ratio)),gy=top+plotH*ratio;return `<g><line class="zx-history-grid-line" x1="${left}" y1="${gy}" x2="${w-right}" y2="${gy}"></line><text class="zx-history-axis-label" x="${left-9}" y="${gy+4}" text-anchor="end">${value}</text></g>`}).join('');const labelIndexes=[0,Math.round((dates.length-1)*.25),Math.round((dates.length-1)*.5),Math.round((dates.length-1)*.75),dates.length-1].filter((value,i,array)=>value>=0&&array.indexOf(value)===i),xLabels=labelIndexes.map(i=>`<text class="zx-history-axis-label" x="${x(i)}" y="${h-10}" text-anchor="middle">${esc((dates[i]||'').slice(5))}</text>`).join(''),dots=values.map((value,i)=>value?`<circle class="zx-history-point" cx="${x(i)}" cy="${y(value)}" r="4" tabindex="0" role="button" data-action="today-history-date" data-history-date="${attr(dates[i])}" data-history-user="${attr(group.uid||'')}" aria-label="${attr(dates[i]+' 新增 '+value+' 位客户')}" style="--history-color:${color}"><title>${esc(dates[i])}：${value} 位，点击查看详情</title></circle>`:'').join(''),gradientId=`zxHistoryGradient${index}`;return `<section class="zx-history-user-card"><div class="zx-history-user-head"><div class="zx-history-user-person"><span class="zx-today-new-user-avatar">${userAvatarMarkup(group.uid||group.key,group.name)}</span><div><strong>${esc(group.name)}</strong><small>全部往期累计 ${group.allTotal} 位${group.todayTotal?` · 今日新增 ${group.todayTotal} 位（不计入往期折线）`:''}</small></div></div><div class="zx-history-user-stats"><span><b>${total}</b>${esc(todayHistoryRangeLabel())}新增</span><span><b>${average.toFixed(1)}</b>日均</span><span><b>${peak}</b>单日最高</span></div></div><div class="zx-history-chart-scroll"><svg class="zx-history-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${attr(group.name+' '+todayHistoryRangeLabel()+'新增客户折线图')}"><defs><linearGradient id="${gradientId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".24"></stop><stop offset="100%" stop-color="${color}" stop-opacity=".02"></stop></linearGradient></defs>${grid}${area?`<path class="zx-history-area" d="${area}" fill="url(#${gradientId})"></path><polyline class="zx-history-line" points="${points}" style="--history-color:${color}"></polyline>`:''}${dots}${xLabels}</svg></div></section>`}
function renderTodayHistoryModal(){const dates=todayHistoryDates(),groups=todayHistoryGroups(dates),selectedTotal=groups.reduce((sum,group)=>sum+dates.reduce((n,date)=>n+(group.counts.get(date)||0),0),0),rangeButtons=[['7','近7天'],['30','近30天'],['90','近90天'],['all','全部']].map(([value,label])=>`<button type="button" class="zx-btn small ${todayHistoryRange===value?'primary':''}" data-today-history-range="${value}">${label}</button>`).join('');return `<div class="zx-today-history"><div class="zx-today-history-toolbar"><div><strong>按创建人查看往期新增趋势</strong><small>统计截至昨日，数据与团队客户库实时联动</small></div><div class="zx-today-history-range" role="group" aria-label="选择统计周期">${rangeButtons}</div></div><div class="zx-today-history-summary"><span><b>${groups.length}</b> 位成员</span><span><b>${selectedTotal}</b> 位新增客户</span><span><b>${dates.length}</b> 个自然日</span></div>${groups.length?`<div class="zx-history-user-list">${groups.map((group,index)=>todayHistoryChart(group,dates,index)).join('')}</div>`:'<div class="zx-empty"><strong>暂无往期新增客户记录</strong>客户新增后会按照创建人自动生成趋势折线图</div>'}</div>`}
function todayHistoryDateCustomers(date,operatorId){const scope=modalStack[modalStack.length-1]?.parentState?.type==='historical-records'?historicalStatusScope:todayNewFilter;return officialCustomers().filter(customer=>localDate(officialJoinedAt(customer))===date&&(!operatorId||String(customerLibraryOperatorId(customer))===String(operatorId))&&(scope!=='mine'||todayNewBelongsToCurrentUser(customer)))}
