const OTHER_SITUATION_RANGES=[['yesterday','昨日'],['7','近 7 天'],['30','近 30 天'],['60','近 60 天'],['90','近 90 天']];
function otherSituationRecordTime(record){return record?.updatedAt||record?.updated_at||record?.createdAt||record?.created_at||''}
function otherSituationRecordOwnerName(record){return String(record?.updatedBy||record?.updated_by_name||record?.updated_by||record?.createdBy||record?.created_by_name||record?.created_by||record?.created_by_username||'未知成员').trim()||'未知成员'}
function otherSituationRecordBelongsToCurrentUser(record){return customerBelongsToCurrentUser(record)}
function otherSituationRangeWindow(range=otherSituationRange){const end=new Date();end.setHours(0,0,0,0);const from=new Date(end);if(range==='yesterday')from.setDate(from.getDate()-1);else from.setDate(from.getDate()-(Math.max(1,Number(range)||7)));return{from,to:end}}
function otherSituationRecordMatches(record,todayMode,scope,range){const at=otherSituationRecordTime(record);if(!at)return false;if(scope==='mine'&&!otherSituationRecordBelongsToCurrentUser(record))return false;if(todayMode)return localDate(at)===today();const window=otherSituationRangeWindow(range);const time=Date.parse(at);return Number.isFinite(time)&&time>=window.from.getTime()&&time<window.to.getTime()}
function otherSituationRecordsForView(todayMode,scope,range){return(state.otherSituationRecords||[]).filter(record=>otherSituationRecordMatches(record,todayMode,scope,range)).sort((a,b)=>(Date.parse(otherSituationRecordTime(b))||0)-(Date.parse(otherSituationRecordTime(a))||0)||String(a.id).localeCompare(String(b.id)))}
function otherSituationReferenceResolved(reference){
 const ref=normalizeOtherSituationReference(reference);if(!ref)return null;
 const source=ref.source==='capture'?(state.captures||[]).find(item=>String(item.id)===ref.id):(state.customers||[]).find(item=>String(item.id)===ref.id);
 if(source)return{...ref,name:String(source.name||source.customer_name||source.douyin_nickname||source.wechat_nickname||ref.name||'未命名客户').trim()||'未命名客户',province:source.province||'',kind:ref.source==='capture'?'客户采集':source.approval==='待确认'?'待确认客户':'客户库'};
 return{...ref,name:ref.name||'已删除客户',province:'',kind:ref.source==='capture'?'客户采集':'客户'};
}
function otherSituationCustomerCandidates(){
 const result=[],seen=new Set();
 (state.customers||[]).forEach(customer=>{const id=String(customer.id||'').trim();if(!id)return;const key=`customer:${id}`;if(seen.has(key))return;seen.add(key);result.push({id,source:'customer',name:String(customer.name||'未命名客户'),province:String(customer.province||''),kind:customer.approval==='待确认'?'待确认客户':'客户库',search:[customer.name,customer.phone,customer.wechat_id,customer.douyin_nickname,customer.org_name,customer.province,customer.city].filter(Boolean).join(' ')})});
 (state.captures||[]).forEach(capture=>{const id=String(capture.id||'').trim();if(!id)return;const key=`capture:${id}`;if(seen.has(key))return;seen.add(key);result.push({id,source:'capture',name:String(capture.name||capture.douyin_nickname||capture.wechat_nickname||'未命名客户'),province:String(capture.province||''),kind:'客户采集',search:[capture.name,capture.douyin_nickname,capture.wechat_nickname,capture.phone,capture.wechat_id,capture.org_name,capture.province,capture.city].filter(Boolean).join(' ')})});
 return result;
}
function otherSituationReferenceChips(record){const refs=(record?.customerRefs||[]).map(otherSituationReferenceResolved).filter(Boolean);return refs.length?`<div class="zx-other-situation-ref-chips">${refs.map(ref=>`<span class="zx-other-situation-ref-chip" title="${attr(ref.kind+'：'+ref.name)}"><span>${esc(ref.name)}</span><small>${esc(ref.kind)}</small><button type="button" data-action="other-situation-remove-ref" data-other-situation-record="${attr(record.id)}" data-other-situation-ref-id="${attr(ref.id)}" data-other-situation-ref-source="${attr(ref.source)}" aria-label="移除 ${attr(ref.name)}">×</button></span>`).join('')}</div>`:'<span class="zx-other-situation-unlinked">未关联客户</span>'}
function otherSituationCustomerPicker(record){
 const key=String(record.id),open=modalState?.otherSituationPickerKey===key;if(!open)return`<button type="button" class="zx-btn small zx-other-situation-link-button" data-action="other-situation-picker-toggle" data-other-situation-record="${attr(key)}">关联客户</button>`;
 const selected=new Set((record.customerRefs||[]).map(ref=>{const item=normalizeOtherSituationReference(ref);return item?`${item.source}:${item.id}`:''}).filter(Boolean));
 const options=otherSituationCustomerCandidates().filter(item=>!selected.has(`${item.source}:${item.id}`)).map(item=>`<button type="button" class="zx-other-situation-ref-option" data-other-situation-option-text="${attr([item.name,item.kind,item.province,item.search].filter(Boolean).join(' ').toLowerCase())}" data-action="other-situation-add-ref" data-other-situation-record="${attr(key)}" data-other-situation-ref-id="${attr(item.id)}" data-other-situation-ref-source="${attr(item.source)}"><strong>${esc(item.name)}</strong><span>${esc(item.kind)}${item.province?' · '+esc(item.province):''}</span></button>`).join('');
 return`<div class="zx-other-situation-picker"><div class="zx-other-situation-picker-head"><strong>搜索并选择客户</strong><button type="button" class="zx-btn small ghost" data-action="other-situation-picker-toggle" data-other-situation-record="${attr(key)}">收起</button></div><input class="zx-input" data-other-situation-customer-search="${attr(key)}" placeholder="搜索姓名、手机号、微信号或机构" autocomplete="off"><div class="zx-other-situation-ref-options">${options||'<span class="zx-other-situation-no-options">暂无可关联客户</span>'}</div></div>`;
}
function otherSituationDraftRecord(id){
 const key=String(id);if(!modalState?.drafts)return null;if(!modalState.drafts[key]){const current=(state.otherSituationRecords||[]).find(record=>String(record.id)===key);if(current)modalState.drafts[key]=cloneData(current)}return modalState.drafts[key]||null;
}
function otherSituationModalRecords(todayMode){
 const scope=modalState?.scope||'all',range=modalState?.range||otherSituationRange,map=new Map(otherSituationRecordsForView(todayMode,scope,range).map(record=>[String(record.id),record]));
 const savingIds=modalState?.savingIds||{};
 Object.values(modalState?.drafts||{}).forEach(record=>{const key=String(record?.id||'');if(!key)return;if(otherSituationRecordMatches(record,todayMode,scope,range)||savingIds[key])map.set(key,record);else map.delete(key)});
 return[...map.values()].sort((a,b)=>(Date.parse(otherSituationRecordTime(b))||0)-(Date.parse(otherSituationRecordTime(a))||0)||String(a.id).localeCompare(String(b.id)));
}
function otherSituationRecordDate(record){return localDate(otherSituationRecordTime(record))}
function otherSituationDateLabel(date){if(!date)return'未设置日期';const parsed=new Date(`${date}T00:00:00`);return Number.isNaN(parsed.getTime())?date:parsed.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',weekday:'short'}).replace(/\//g,'-')}
function otherSituationRecordGroups(records){const groups=new Map();records.forEach(record=>{const date=otherSituationRecordDate(record)||'unknown';if(!groups.has(date))groups.set(date,[]);groups.get(date).push(record)});return[...groups.entries()].sort((a,b)=>{if(a[0]==='unknown')return 1;if(b[0]==='unknown')return-1;return b[0].localeCompare(a[0])})}
function renderOtherSituationDateGroups(records){const groups=otherSituationRecordGroups(records);return groups.length?`<div class="zx-other-situation-date-groups" role="list">${groups.map(([date,list])=>`<button type="button" class="zx-other-situation-date-group" data-action="other-situation-date" data-other-situation-date="${attr(date)}" role="listitem"><span><strong>${esc(otherSituationDateLabel(date))}</strong><small>${date==='unknown'?'时间缺失':'自然日记录'}</small></span><b>${list.length} 条</b><span class="zx-other-situation-date-arrow" aria-hidden="true">›</span></button>`).join('')}</div>`:'<div class="zx-empty"><strong>当前时间范围暂无记录</strong>切换其他时间范围查看记录。</div>'}
