function otherSituationRecordControls(record){const key=String(record.id),busy=Boolean(modalState?.savingIds?.[key]);return`<div class="zx-other-situation-record-controls"><button type="button" class="zx-btn small primary" data-action="other-situation-save" data-other-situation-record="${attr(key)}" ${busy?'disabled':''}>${busy?'保存中…':'保存'}</button><button type="button" class="zx-btn small danger" data-action="other-situation-delete" data-other-situation-record="${attr(key)}" ${busy?'disabled':''}>删除</button></div>`}
function renderOtherSituationInputRecords(records){return records.length?`<div class="zx-other-situation-input-list">${records.map((record,index)=>`<article class="zx-other-situation-input-record"><div class="zx-other-situation-record-head"><div><strong>记录 ${index+1}</strong>${otherSituationRecordMeta(record)}</div>${otherSituationRecordControls(record)}</div><textarea class="zx-textarea zx-other-situation-content" data-other-situation-content data-other-situation-record="${attr(record.id)}" placeholder="填写今天的其他情况">${esc(record.content||'')}</textarea><div class="zx-other-situation-associations"><div class="zx-other-situation-association-head"><strong>关联客户</strong>${otherSituationCustomerPicker(record)}</div>${otherSituationReferenceChips(record)}</div></article>`).join('')}</div>`:'<div class="zx-empty"><strong>暂无记录</strong>点击“新增记录”开始填写。</div>'}
function renderOtherSituationExcelRecords(records){return records.length?`<div class="zx-other-situation-excel-wrap"><table class="zx-table zx-other-situation-excel"><colgroup><col class="other-situation-index"><col class="other-situation-content"><col class="other-situation-customers"><col class="other-situation-actions"></colgroup><thead><tr><th>序号</th><th>内容</th><th>关联客户</th><th>操作</th></tr></thead><tbody>${records.map((record,index)=>`<tr><td>${index+1}</td><td><textarea class="zx-textarea zx-other-situation-content" data-other-situation-content data-other-situation-record="${attr(record.id)}" placeholder="填写内容">${esc(record.content||'')}</textarea><div>${otherSituationRecordMeta(record)}</div></td><td><div class="zx-other-situation-associations"><div class="zx-other-situation-association-head">${otherSituationCustomerPicker(record)}</div>${otherSituationReferenceChips(record)}</div></td><td>${otherSituationRecordControls(record)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="zx-empty"><strong>暂无记录</strong>点击“新增记录”开始填写。</div>'}
function renderOtherSituationModal(todayMode=true,options={}){
 const scope=modalState?.scope||(todayMode?todayNewFilter:otherSituationScope),range=modalState?.range||otherSituationRange,mode=modalState?.mode||otherSituationMode,records=otherSituationModalRecords(todayMode),selectedDate=!todayMode?String(modalState?.date||''):'';
 const rangeMarkup=todayMode?'':`<div class="zx-other-situation-ranges" role="tablist" aria-label="选择时间范围">${OTHER_SITUATION_RANGES.map(([value,label])=>`<button type="button" class="zx-btn small ${range===value?'primary':'ghost'}" data-action="other-situation-range" data-range="${value}" aria-pressed="${range===value}">${label}</button>`).join('')}</div>`;
 const selectedRecords=selectedDate?records.filter(record=>otherSituationRecordDate(record)===selectedDate||modalState?.savingIds?.[String(record.id)]):records;
 const dateMarkup=!todayMode&&!selectedDate?renderOtherSituationDateGroups(records):'';
 const dayMarkup=!todayMode&&selectedDate?`<div class="zx-other-situation-selected-date"><button type="button" class="zx-btn small ghost" data-action="other-situation-date-back">返回日期分组</button><strong>${esc(otherSituationDateLabel(selectedDate))}</strong><span>${selectedRecords.length} 条记录</span></div>`:'';
 const recordMarkup=todayMode||selectedDate?(mode==='excel'?renderOtherSituationExcelRecords(selectedRecords):renderOtherSituationInputRecords(selectedRecords)):dateMarkup;
 const scopeMarkup=options.includeScope===false?'':otherSituationScopeButtons(scope);
 return`<div class="zx-other-situation"><div class="zx-other-situation-toolbar"><div class="zx-other-situation-toolbar-title"><strong>${todayMode?'今日其他情况记录':'往期其他情况记录'}</strong>${todayMode?'':`<small>当前范围：${esc(OTHER_SITUATION_RANGES.find(item=>item[0]===range)?.[1]||'昨日')}，按自然日统计</small>`}</div><div class="zx-other-situation-toolbar-controls">${scopeMarkup}<div class="zx-other-situation-modes" role="tablist" aria-label="记录编辑模式"><button type="button" class="zx-btn small ${mode==='input'?'primary':'ghost'}" data-action="other-situation-mode" data-mode="input" aria-selected="${mode==='input'}">输入模式</button><button type="button" class="zx-btn small ${mode==='excel'?'primary':'ghost'}" data-action="other-situation-mode" data-mode="excel" aria-selected="${mode==='excel'}">Excel 模式</button></div>${rangeMarkup}<button type="button" class="zx-btn small primary" data-action="other-situation-add">＋ 新增记录</button></div></div>${dayMarkup}${recordMarkup}</div>`;
}
function showTodayOtherSituations(){modalState={type:'other-situations-today',scope:todayNewFilter,mode:otherSituationMode,drafts:{},savingIds:{},otherSituationPickerKey:''};modal('今日其他情况记录',renderOtherSituationModal(true),'<button class="zx-btn" data-action="close-modal">关闭</button>',true,true,'zx-other-situation-modal')}
function showHistoricalOtherSituations(){modalState={type:'historical-other-situations',scope:otherSituationScope,range:otherSituationRange,mode:otherSituationMode,drafts:{},savingIds:{},otherSituationPickerKey:''};modal('往期其他情况记录',renderOtherSituationModal(false),'<button class="zx-btn" data-action="close-modal">关闭</button>',true,true,'zx-other-situation-modal')}
function isOtherSituationModalContext(value=modalState){return Boolean(value&&(['other-situations-today','historical-other-situations'].includes(value.type)||(value.type==='historical-records'&&historicalRecordTab==='other')))}
function refreshOtherSituationModal(){if(!isOtherSituationModalContext())return;if(modalState.type==='historical-records'){refreshHistoricalRecordsModal();return}const body=activeModalElement()?.querySelector('.zx-modal-body');if(body)body.innerHTML=renderOtherSituationModal(modalState.type==='other-situations-today')}
function refreshOtherSituationRecordParent(){if(modalState?.type==='historical-records')refreshHistoricalRecordsModal();else refreshOtherSituationModal()}
function addOtherSituationRecord(){if(!isOtherSituationModalContext())return;const user=currentUser(),stamp=now(),id=uid('other-situation');modalState.drafts=modalState.drafts||{};modalState.drafts[id]={id,content:'',customerRefs:[],createdAt:stamp,updatedAt:stamp,created_by_user_id:user.id??'',createdBy:user.display_name||user.username||'',updated_by_user_id:user.id??'',updatedBy:user.display_name||user.username||'',updated_by_username:user.username||''};refreshOtherSituationModal();setTimeout(()=>document.querySelector(`[data-other-situation-content][data-other-situation-record="${CSS.escape(id)}"]`)?.focus(),0)}
function otherSituationSaveLock(key,callback){const previous=otherSituationSaveTails.get(key)||Promise.resolve();let release;const current=new Promise(resolve=>{release=resolve});otherSituationSaveTails.set(key,current);return previous.catch(()=>{}).then(callback).finally(()=>{release();if(otherSituationSaveTails.get(key)===current)otherSituationSaveTails.delete(key)})}
async function persistOtherSituationChange(id,nextRecord,message){
 const key=String(id),noticeKey=`other-situation:${key}`;operationNotice(noticeKey,`${message}，保存中…`,'pending');
 return otherSituationSaveLock(key,async()=>{
  if(!syncState.ready){operationNotice(noticeKey,'保存失败：团队同步尚未准备好，请稍后再试','error');return false}
  let currentBase=cloneData(syncState.base||state),currentVersion=Number(syncState.version||0),conflictAttempts=0;
  const buildPatch=base=>{const previous=Array.isArray(base?.otherSituationRecords)?base.otherSituationRecords:[],next=previous.filter(record=>String(record.id)!==key);if(nextRecord)next.push(cloneData(nextRecord));const change=syncArrayPatch(previous,next,'otherSituationRecords');return{replace:{},arrays:change.replace!==undefined||change.add?.length||change.update?.length||change.remove?.length?{otherSituationRecords:change}:{}}};
  let patch=buildPatch(currentBase);if(syncPatchEmpty(patch)){operationNotice(noticeKey,message,'success');return true}
  try{
   while(true){
    const rid=`other-situation-${requestId()}`;try{const response=await requestCustomerPatchWithRetry('/api/sync/patch-batch',{method:'POST',headers:{'Content-Type':'application/json','X-Request-Id':rid},body:JSON.stringify({operationId:`other-situation-${key}`,batchIndex:0,totalBatches:1,baseVersion:currentVersion,patch,requestId:rid})});syncState.version=Number(response.version||syncState.version);syncState.cursor=Math.max(syncState.cursor,Number(response.cursor||0));const accepted=applySyncPatch(currentBase,patch),merged=mergeConcurrentState(currentBase,state,accepted);syncState.applying=true;try{state=repair(merged);persistLocalState();syncState.base=cloneData(accepted);syncState.pending=!sameData(state,accepted)}finally{syncState.applying=false}if(syncState.pending)persistSyncOutbox();else{clearSyncOutbox();resetSyncRetryState()}writeSyncMeta();operationNotice(noticeKey,message,'success');void pullTeamChanges(true);return true}catch(error){if(error.status!==409||!error.data?.state||conflictAttempts>=4)throw error;currentBase=repair(error.data.state);currentVersion=Number(error.data.version||0);patch=buildPatch(currentBase);conflictAttempts+=1}}
  }catch(error){let remoteState=error?.data?.state?repair(error.data.state):null;if(!remoteState){try{const snapshot=await syncFetch('/api/sync/snapshot');remoteState=snapshot?.state?repair(snapshot.state):null;if(snapshot){syncState.version=Number(snapshot.version||syncState.version);syncState.cursor=Math.max(syncState.cursor,Number(snapshot.cursor||0))}}catch(_){} }if(remoteState){syncState.applying=true;try{state=repair(mergeConcurrentState(currentBase,state,remoteState));persistLocalState();syncState.base=cloneData(remoteState)}finally{syncState.applying=false}writeSyncMeta()}operationNotice(noticeKey,error.message||'其他情况记录保存失败，服务端未接受本次修改','error');return false}
 });
}
async function saveOtherSituationRecord(id){const context=modalState;if(!isOtherSituationModalContext(context)||context.savingIds?.[String(id)])return;const key=String(id),current=(state.otherSituationRecords||[]).find(record=>String(record.id)===key),draft=context.drafts?.[key]||cloneData(current);if(!draft)return;if(!String(draft.content||'').trim())return toast('请先填写记录内容','error');const user=currentUser(),next=normalizeOtherSituationRecord(draft);next.content=String(draft.content||'').trim();next.customerRefs=(draft.customerRefs||[]).map(normalizeOtherSituationReference).filter(Boolean);next.updatedAt=now();next.updated_by_user_id=user.id??'';next.updatedBy=user.display_name||user.username||'';next.updated_by_username=user.username||'';if(!current){next.createdAt=draft.createdAt||next.updatedAt;next.created_by_user_id=draft.created_by_user_id??user.id??'';next.createdBy=draft.createdBy||user.display_name||user.username||''}context.savingIds=context.savingIds||{};context.savingIds[key]=true;context.drafts[key]=next;refreshOtherSituationModal();const ok=await persistOtherSituationChange(key,next,current?'其他情况记录已更新':'其他情况记录已新增');delete context.savingIds[key];if(ok){delete context.drafts[key];if(context.type!=='other-situations-today')context.date=''}else if(current)context.drafts[key]=cloneData(current);if(modalState===context)refreshOtherSituationModal()}
async function deleteOtherSituationRecord(id){const context=modalState;if(!isOtherSituationModalContext(context))return;const key=String(id),current=(state.otherSituationRecords||[]).find(record=>String(record.id)===key);if(!current){delete context.drafts[key];refreshOtherSituationModal();return}if(!window.confirm('确定删除这条其他情况记录吗？'))return;context.savingIds=context.savingIds||{};context.savingIds[key]=true;refreshOtherSituationModal();const ok=await persistOtherSituationChange(key,null,'其他情况记录已删除');delete context.savingIds[key];if(ok){delete context.drafts[key];if(context.type!=='other-situations-today')context.date=''}if(modalState===context)refreshOtherSituationModal()}
function localTodayStatusChangeRecords(){const start=new Date();start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+1);const grouped=new Map();officialCustomers().forEach(customer=>{const joinedAt=officialJoinedTime(customer),history=Array.isArray(customer.statusHistory)?customer.statusHistory:[];history.forEach((item,index)=>{const at=item?.at??item?.createdAt??item?.created_at??item?.changedAt??item?.changed_at??'',time=Date.parse(at||'');if(!Number.isFinite(time)||time<start.getTime()||time>=end.getTime()||(joinedAt&&time<joinedAt)||item?.reason==='客户创建时设置销售状态')return;const from=String(item?.from??item?.from_status??'').trim(),to=String(item?.to??item?.to_status??'').trim();if(!from||!to||from===to)return;const operatorId=String(item?.operatorUserId??item?.operator_user_id??item?.userId??item?.user_id??'').trim(),operatorName=String(item?.user??item?.operatorDisplayName??item?.operator_display_name??item?.operator_username??'').trim(),record={customerId:String(customer.id),customerName:customer.name||'未命名客户',from,to,operatorId,operatorName:operatorName||userName(operatorId)||'未知成员',at,time,index};if(!grouped.has(record.customerId))grouped.set(record.customerId,[]);grouped.get(record.customerId).push(record)})});return [...grouped.values()].map(items=>{items.sort((a,b)=>a.time-b.time||a.index-b.index);const first=items[0],latest=items[items.length-1];return{...latest,from:first.from,firstAt:first.at,firstTime:first.time}})}
function normalizeRemoteStatusChange(item){const customerId=String(item?.customer_id??item?.customerId??'').trim(),customer=state.customers.find(row=>String(row.id)===customerId),operatorId=String(item?.operator_user_id??item?.operatorUserId??'').trim(),operatorName=String(item?.operator_display_name||item?.operator_username||'').trim();const at=item?.created_at||item?.createdAt||'';return{customerId,customerName:customer?.name||item?.customer_name||'未命名客户',from:String(item?.first_from_status??item?.from_status??item?.from??'').trim()||'未设置',to:String(item?.latest_to_status??item?.to_status??item?.to??'').trim()||'未设置',operatorId,operatorName:operatorName||userName(operatorId)||'未知成员',at,time:Date.parse(at)||0,firstAt:item?.first_created_at||item?.firstCreatedAt||at,firstTime:Date.parse(item?.first_created_at||item?.firstCreatedAt||at)||0,index:Number(item?.id||0)}}
function filterTodayStatusChangeRecords(records,scope){const user=currentUser(),currentUserId=String(user?.id??'').trim(),currentUserName=String(user?.display_name||user?.username||'').trim();return records.filter(record=>{if(scope!=='mine')return true;if(record.operatorId)return Boolean(currentUserId)&&record.operatorId===currentUserId;return record.operatorName===currentUserName}).sort((a,b)=>b.time-a.time||a.customerName.localeCompare(b.customerName,'zh-CN'))}
function todayStatusChangeRecords(scope=todayStatusChangeScope){const date=today(),source=todayStatusChangeRemote.loaded&&todayStatusChangeRemote.date===date?todayStatusChangeRemote.records:localTodayStatusChangeRecords();return filterTodayStatusChangeRecords(source,scope)}
async function loadTodayStatusChanges(force=false){if(!syncState.ready||todayStatusChangeRemote.loading)return;const date=today();if(!force&&todayStatusChangeRemote.loaded&&todayStatusChangeRemote.date===date)return;const requestIdValue=++todayStatusChangeRemote.requestId;todayStatusChangeRemote.loading=true;try{const data=await syncFetch(`/api/sync/status-history/today?date=${encodeURIComponent(date)}&limit=2000`);if(requestIdValue!==todayStatusChangeRemote.requestId)return;todayStatusChangeRemote={date,records:(data.records||[]).map(normalizeRemoteStatusChange),total:Number(data.total||0),loading:false,loaded:true,error:'',requestId:requestIdValue};const parentStatusLayer=modalStack.find(layer=>layer.parentState?.type==='today-status-changes');if(modalState?.type==='today-status-changes'||parentStatusLayer){const parentId=parentStatusLayer?.parentId||'zxModal',modalElement=document.getElementById(parentId),body=modalElement?.querySelector('.zx-modal-body');if(body)body.innerHTML=renderTodayStatusChangesModal();updateTodayStatusChangeModalHeader(modalElement)}else if(route()==='dashboard')render()}catch(error){if(requestIdValue!==todayStatusChangeRemote.requestId)return;todayStatusChangeRemote.loading=false;todayStatusChangeRemote.error=error.message||'今日状态变更读取失败';const parentStatusLayer=modalStack.find(layer=>layer.parentState?.type==='today-status-changes');if(modalState?.type==='today-status-changes'||parentStatusLayer)updateTodayStatusChangeModalHeader(document.getElementById(parentStatusLayer?.parentId||'zxModal'));else if(route()==='dashboard')render()}}
function todayStatusChangeStatusGroups(records){const groups=new Map();records.forEach(record=>{if(!groups.has(record.to))groups.set(record.to,[]);groups.get(record.to).push(record)});return [...groups.entries()].sort((a,b)=>b[1].length-a[1].length||a[0].localeCompare(b[0],'zh-CN'))}
function todayStatusChangeStatusPills(records,activeStatus=todayStatusChangeStatus){const tabs=[['','全部',records.length],...todayStatusChangeStatusGroups(records).map(([status,list])=>[status,status,list.length])];return tabs.map(([status,label,count])=>`<button type="button" class="zx-status-pill ${activeStatus===status?'active':''}" style="--pill:${status?statusColor(status):'#315efb'}" data-action="today-status-filter" data-status="${attr(status)}" role="tab" aria-selected="${activeStatus===status}">${esc(label)} <b>${count}</b></button>`).join('')}
function todayStatusChangeCards(records){return records.length?`<div class="zx-today-status-change-list">${records.map(record=>{const color=statusColor(record.to);return `<article class="zx-today-status-change-card" data-open-customer="${attr(record.customerId)}" title="点击查看客户详情"><div class="zx-today-status-change-card-head"><strong>${esc(record.customerName)}</strong><span class="zx-badge" style="background:${color}16;color:${color};border:1px solid ${color}33">${esc(record.to)}</span></div><div class="zx-today-status-change-transition"><span>${esc(record.from)}</span><b>→</b><span style="color:${color}">${esc(record.to)}</span></div><dl><div><dt>修改时间</dt><dd>${esc(fmt(record.at))}</dd></div></dl></article>`}).join('')}</div>`:'<div class="zx-empty"><strong>当前筛选暂无销售状态变更</strong>切换状态标签或查看范围后重试</div>'}
function renderTodayStatusChangesModal(){const records=todayStatusChangeRecords(),selectedRecords=todayStatusChangeStatus?records.filter(record=>record.to===todayStatusChangeStatus):records,allUserGroups=new Map();records.forEach(record=>{const key=record.operatorId?`id:${record.operatorId}`:`name:${record.operatorName||'未知成员'}`;if(!allUserGroups.has(key))allUserGroups.set(key,{name:record.operatorName||userName(record.operatorId)||'未知成员',records:[]});allUserGroups.get(key).records.push(record)});const userGroups=[...allUserGroups.values()].sort((a,b)=>b.records.length-a.records.length||a.name.localeCompare(b.name,'zh-CN'));const userSections=userGroups.map(group=>{const selected=group.records.filter(record=>!todayStatusChangeStatus||record.to===todayStatusChangeStatus);return selected.length?`<section class="zx-today-status-change-user-group"><div class="zx-today-status-change-user-head"><div><strong>${esc(group.name)}</strong><small>今日变更 <b>${group.records.length}</b> 位客户</small></div><div class="zx-today-status-change-user-statuses">${todayStatusChangeStatusGroups(group.records).map(([status,list])=>`<span class="zx-status-pill" style="--pill:${statusColor(status)}">${esc(status)} <b>${list.length}</b></span>`).join('')}</div></div>${todayStatusChangeCards(selected)}</section>`:''}).join('');const loadingNote=todayStatusChangeRemote.loading?'正在从服务器读取完整记录…':todayStatusChangeRemote.error?`读取服务器统计失败，当前显示本地记录：${esc(todayStatusChangeRemote.error)}`:'';return `<div class="zx-today-status-change"><div class="zx-today-status-change-toolbar"><div><strong>客户库今日销售状态变更</strong><small>统计日期：${esc(today())}（00:00:00—23:59:59） · 共 ${records.length} 位客户</small>${loadingNote?`<small class="zx-today-status-change-loading">${loadingNote}</small>`:''}</div><div class="zx-today-status-change-scope" role="group" aria-label="状态变更查看范围"><button type="button" class="zx-btn small ${todayStatusChangeScope==='mine'?'primary':'ghost'}" data-action="today-status-scope" data-scope="mine" aria-pressed="${todayStatusChangeScope==='mine'}">自己</button><button type="button" class="zx-btn small ${todayStatusChangeScope==='all'?'primary':'ghost'}" data-action="today-status-scope" data-scope="all" aria-pressed="${todayStatusChangeScope==='all'}">全部</button></div></div><div class="zx-today-status-change-tabs" role="tablist">${todayStatusChangeStatusPills(records)}</div>${todayStatusChangeScope==='all'?`<div class="zx-today-status-change-user-groups">${userSections||'<div class="zx-empty"><strong>今天暂无销售状态变更</strong>客户状态发生变化后，会在这里按用户实时显示</div>'}</div>`:todayStatusChangeCards(selectedRecords)}</div>`}
function showTodayStatusChanges(){modalState={type:'today-status-changes'};const element=modal(todayStatusChangeModalHeader(),renderTodayStatusChangesModal(),'<button class="zx-btn" data-action="close-modal">关闭</button>',true,true,'zx-today-status-change-modal');updateTodayStatusChangeModalHeader(element)}
function historicalStatusWindow(range=historicalStatusRange){const now=new Date(),to=new Date(now),from=new Date(now);if(range==='yesterday'){to.setHours(0,0,0,0);from.setTime(to.getTime());from.setDate(from.getDate()-1)}else{to.setHours(0,0,0,0);from.setTime(to.getTime());from.setDate(from.getDate()-(Math.max(1,Number(range)||7)))}return{from,to}}
function historicalStatusRangeLabel(range=historicalStatusRange){return range==='yesterday'?'昨日（过去24小时）':`近 ${range} 天（不含今天）`}
function historicalStatusRangeKey(range=historicalStatusRange){return String(range||'yesterday')}
function normalizeHistoricalStatusChange(item){const customerId=String(item?.customer_id??item?.customerId??'').trim(),customer=state.customers.find(row=>String(row.id)===customerId),operatorId=String(item?.operator_user_id??item?.operatorUserId??'').trim(),operatorName=String(item?.operator_display_name||item?.operator_username||item?.user||'').trim(),at=item?.created_at||item?.createdAt||item?.at||'';return{customerId,customerName:customer?.name||item?.customer_name||'未命名客户',from:String(item?.from_status??item?.from??'').trim()||'未设置',to:String(item?.to_status??item?.to??'').trim()||'未设置',operatorId,operatorName:operatorName||userName(operatorId)||'未知成员',requestId:String(item?.request_id??item?.requestId??'').trim(),reason:item?.reason||'销售状态变更',at,time:Date.parse(at)||0,index:Number(item?.id||0)}}
function localHistoricalStatusChangeRecords(range=historicalStatusRange){const window=historicalStatusWindow(range),records=[];officialCustomers().forEach(customer=>{const joinedTime=officialJoinedTime(customer);(Array.isArray(customer.statusHistory)?customer.statusHistory:[]).forEach((item,index)=>{const at=item?.at??item?.createdAt??item?.created_at??item?.changedAt??item?.changed_at??'',time=Date.parse(at||'');if(!Number.isFinite(time)||time<window.from.getTime()||time>=window.to.getTime()||(joinedTime&&time+1000<joinedTime)||item?.reason==='客户创建时设置销售状态')return;const from=String(item?.from??item?.from_status??'').trim(),to=String(item?.to??item?.to_status??'').trim();if(!from||!to||from===to)return;const operatorId=String(item?.operatorUserId??item?.operator_user_id??item?.userId??item?.user_id??'').trim(),operatorName=String(item?.user??item?.operatorDisplayName??item?.operator_display_name??item?.operator_username??'').trim();records.push({customerId:String(customer.id),customerName:customer.name||'未命名客户',from,to,operatorId,operatorName:operatorName||userName(operatorId)||'未知成员',requestId:String(item?.requestId??item?.request_id??'').trim(),reason:item?.reason||'销售状态变更',at,time,index})})});return records}
