function todayStatusChangeDisplayRecords(){
 const date=today(),remote=todayStatusChangeRemote.loaded&&todayStatusChangeRemote.date===date?todayStatusChangeRemote.records:[],source=[...localTodayStatusChangeRecords(),...remote],grouped=new Map();
 source.forEach(record=>{
  const customer=customerById(record.customerId);
  if(!customer||customer.approval==='待确认'||localDate(officialJoinedAt(customer))>=date)return;
  const current=grouped.get(String(record.customerId));
  if(!current||record.time>current.time||(record.time===current.time&&Number(record.index||0)>Number(current.index||0)))grouped.set(String(record.customerId),record);
 });
 return filterTodayStatusChangeRecords([...grouped.values()],todayStatusChangeScope);
}
