// 客户采集：抖音复制文本会把"抖音号 + 获赞数"连在一起，需先拆分再识别抖音号。
function captureMetricNumber(value){var raw=String(value||'').trim();var n=parseFloat(raw)||0;if(raw.indexOf('万')>=0)n*=10000;else if(raw.indexOf('亿')>=0)n*=100000000;return n}
