function computeColWidths(rows,headers){var BASE_BY_HEADER={'序号':6.8,'省份':10.8,'销售状态':24.1,'姓名':27.7,'手机号':15.8,'客户身份':16.8,'机构名称':38.8,'微信昵称':31.2,'微信号':25.3,'QQ号':18.0,'抖音昵称':46.9,'抖音号':33.6,'视频号':32.7,'公众号':24.2,'城市':14.0,'抖音粉丝量':15.8,'备注':40.8};return headers.map(function(h){var base={wch:BASE_BY_HEADER[h]||12};var maxLen=h.length;rows.forEach(function(row){var v=String(row[h]||'');var len=0;for(var i=0;i<v.length;i++){var ch=v.charAt(i);len+=/[一-鿿]/.test(ch)?2.0:1.2}maxLen=Math.max(maxLen,len+2)});return{wch:Math.min(Math.max(maxLen,base.wch),60)}})}
