async function captureAddToPending(idx,updatedEntry){
 const original=state.captures[idx],source=updatedEntry?{...original,...updatedEntry}:original;
 if(!original||!source||!captureBelongsToCurrentUser(original)){toast('数据不存在或无权操作','error');return false}
 const customer=captureLibraryCustomer(source),duplicates=captureOfficialDuplicateMatches(customer),captureId=String(original.id||'');
 if(duplicates.length){if(updatedEntry){Object.assign(original,updatedEntry);save('采集客户信息已更新')}if(modalState?.type==='capture-customer-comparison')toast('当前采集客户仍与客户库重复，请先修改客户信息','error');else showCaptureCustomerDuplicateWarning(duplicates,original);return false}
 if(!syncState.ready){toast('团队同步尚未准备好，请稍后再试','error');return false}
 if(singleCapturePromotionIds.has(captureId)){toast('该客户正在加入客户库，请稍后','info');return false}
 const importId=`capture-promote-single-${requestId()}`,requestIdValue=requestId(),noticeKey=`capture-promote:${captureId}`;
 singleCapturePromotionIds.add(captureId);operationNotice(noticeKey,`正在将“${customer.name}”加入客户库…`,'pending');
 try{
  const response=await syncRequestWithRetry('/api/sync/promote-capture-batch',{method:'POST',headers:{'Content-Type':'application/json','X-Request-Id':requestIdValue},body:JSON.stringify({importId,batchIndex:0,totalBatches:1,captureIds:[captureId],captures:[cloneData(source)]})},'客户采集加入客户库');
  const acceptedCaptureIds=Array.isArray(response.acceptedCaptureIds)?response.acceptedCaptureIds.map(String):[];
  if(Number(response.accepted||0)>0&&acceptedCaptureIds.includes(captureId)){
   applyAcceptedCapturePromotion(acceptedCaptureIds);
   render();
   refreshPromotionChangesInBackground();
   operationNotice(noticeKey,'已加入客户库','success');return true
  }
  const retained=currentUserCaptureById(captureId)||source,remoteDuplicates=captureOfficialDuplicateMatches(retained);
  if(remoteDuplicates.length)showCaptureCustomerDuplicateWarning(remoteDuplicates,retained);
  else operationNotice(noticeKey,'未能加入客户库，原记录已保留在客户采集','error');
  return false;
 }catch(error){
  try{const snapshot=await syncFetch('/api/sync/snapshot');if(snapshot?.state)applyIncomingSnapshot(snapshot)}catch(_){}
  operationNotice(noticeKey,error.message||'加入客户库失败，原记录已保留在客户采集','error');return false;
 }finally{singleCapturePromotionIds.delete(captureId)}
}
function captureBatchDelete(){
 if(captureDeletionJob){if(captureDeletionJob.failed&&!syncState.importing)return runCaptureDeletionJob();return}
 // 虚拟列表只挂载当前视口附近的行；删除必须以完整选中状态为准。
 var selected=visibleCaptureRows(currentUserCaptures()).filter(function(capture){return capture._selected});
 if(!selected.length)return toast('请先勾选要删除的客户','error');
 if(!confirm('确定删除已勾选的 '+selected.length+' 条采集数据吗？'))return;
 var batches=[];
 for(var index=0;index<selected.length;index+=IMPORT_BATCH_MAX_ROWS){
  batches.push(selected.slice(index,index+IMPORT_BATCH_MAX_ROWS).map(function(capture){return String(capture.id)}));
 }
 captureDeletionJob={kind:'captureDelete',label:'批量删除客户采集',importId:'capture-delete-'+requestId(),batches:batches,nextBatch:0,totalBatches:batches.length,deleted:0,skipped:0,skippedIds:[],batchResults:{},failed:false};
 selected.forEach(function(capture){capture._selected=false});
 runCaptureDeletionJob();
}
function captureAdd(){const cs=state.captureSession;const city=$('#captureCity')?.value||'';const entry={id:uid('capture'),...captureOwnerFields(),sessionId:cs._sid,province:cs.province,identity:cs.identity,city,douyin_nickname:$('#captureDouyinNickname')?.value?.trim()||'',douyin_id:$('#captureDouyinId')?.value?.trim()||'',name:$('#captureName')?.value?.trim()||'',phone:$('#capturePhone')?.value?.trim()||'',org_name:$('#captureOrgName')?.value?.trim()||'',douyin_followers:normalizeFollowerText($('#captureFollowers')?.value),remark:$('#captureRemark')?.value?.trim()||'',createdAt:now()};if(!entry.douyin_nickname&&!entry.name)return toast('请至少填写抖音昵称或姓名','error');state.captures.unshift(entry);if(entry.city)captureCityDone()[entry.city]='done';cs._activeCity=entry.city;save('客户已录入');log('采集录入',`${entry.name||entry.douyin_nickname} · ${entry.city||''}`);['captureDouyinNickname','captureDouyinId','captureName','capturePhone','captureOrgName','captureFollowers','captureRemark'].forEach(id=>{const el=$('#'+id);if(el)el.value=''});render()}
function renderCustomers(){
 const tab=customerFilter.tab;let body=tab==='feedback'?renderFeedbackView():tab==='dedupe'?renderDuplicateView():tab==='capture'?renderCaptureView():renderCustomerMain();
 return shell(`<div class="zx-actions" style="margin-bottom:14px"><button class="zx-btn" data-action="import-customers">批量导入</button><button class="zx-btn" data-action="export-customers">导出客户信息</button><button class="zx-btn primary" data-action="new-customer">新增客户至客户库</button></div><section class="zx-card"><div class="zx-tabs"><button class="zx-tab ${tab==='all'?'active':''}" data-customer-tab="all">客户库 <span class="count">${scopedOfficialCustomers().length}</span></button><button class="zx-tab ${tab==='pending'?'active':''}" data-customer-tab="pending">待确认客户 <span class="count">${state.customers.filter(c=>c.approval==='待确认').length}</span></button><button class="zx-tab ${tab==='capture'?'active':''}" data-customer-tab="capture">客户采集 <span class="count">${pendingCaptures().length}</span></button><button class="zx-tab ${tab==='feedback'?'active':''}" data-customer-tab="feedback">客户反馈 <span class="count">${state.feedback.length}</span></button><button class="zx-tab ${tab==='dedupe'?'active':''}" data-customer-tab="dedupe">客户去重 <span class="count">${duplicateGroupsTabCount()}</span></button></div>${body}</section>`);
}
function knowledgeItems(type){return type==='scripts'?state.scripts:type==='experiences'?state.experiences:state.materials}
function normalizeKnowledgeType(type){const value=String(type||'').toLowerCase();return value==='scripts'||value==='script'?'script':value==='experiences'||value==='experience'?'experience':value==='materials'||value==='material'?'material':''}
function knowledgeStateKey(type){return normalizeKnowledgeType(type)==='script'?'scripts':normalizeKnowledgeType(type)==='experience'?'experiences':'materials'}
function knowledgeItemId(type,item){const normalized=normalizeKnowledgeType(type);if(!item)return'';const value=normalized==='material'?(item.serverId||item.id):item.id;return normalized==='material'&&String(value).startsWith('server_')?String(value).slice(7):String(value??'')}
function knowledgeRef(type,id){return`${normalizeKnowledgeType(type)}:${String(id??'')}`}
function parseKnowledgeRef(value){const text=String(value||''),index=text.indexOf(':');return index<0?{type:'',id:''}:{type:normalizeKnowledgeType(text.slice(0,index)),id:text.slice(index+1)}}
function knowledgeItem(type,id){const normalized=normalizeKnowledgeType(type),wanted=normalized==='material'&&String(id).startsWith('server_')?String(id).slice(7):String(id);const item=knowledgeItems(knowledgeStateKey(normalized)).find(entry=>knowledgeItemId(normalized,entry)===wanted);return item||null}
function knowledgeItemTitle(type,item){return item?.title||item?.original_name||item?.name||(normalizeKnowledgeType(type)==='material'?'未命名文件':'未命名内容')}
function relationOtherSide(relation,type,id){const ref=knowledgeRef(type,id);if(knowledgeRef(relation.sourceType,relation.sourceId)===ref)return{type:normalizeKnowledgeType(relation.targetType),id:String(relation.targetId),item:relation.targetItem};if(knowledgeRef(relation.targetType,relation.targetId)===ref)return{type:normalizeKnowledgeType(relation.sourceType),id:String(relation.sourceId),item:relation.sourceItem};return null}
function relatedKnowledge(type,id,targetType=''){return knowledgeRelations.map(relation=>{const other=relationOtherSide(relation,type,id);if(!other||targetType&&other.type!==normalizeKnowledgeType(targetType))return null;return{relation,...other,item:knowledgeItem(other.type,other.id)||other.item}}).filter(entry=>entry&&entry.item)}
async function knowledgeRequest(url,options={}){const response=await window.ZhiXunAuth.fetch(url,options);let data={};try{data=await response.json()}catch(_){}if(!response.ok)throw new Error(data.error||`关联服务返回 ${response.status}`);return data}
async function loadKnowledgeRelations(renderPage=false){if(knowledgeRelationsHydrating||!window.ZhiXunAuth?.getToken?.())return;knowledgeRelationsHydrating=true;try{const payload=await knowledgeRequest('/api/knowledge/relations');knowledgeRelations=Array.isArray(payload.data)?payload.data:[];if(renderPage&&route()==='knowledge'&&!modalState)render()}catch(_){/* 保留当前关联缓存并等待下一次同步 */}finally{knowledgeRelationsHydrating=false}}
async function replaceKnowledgeRelations(experienceId,relations){const payload=await knowledgeRequest(`/api/knowledge/experience/${encodeURIComponent(experienceId)}/relations`,{method:'PUT',headers:{'Content-Type':'application/json','X-Request-Id':requestId()},body:JSON.stringify({relations})});knowledgeRelations=knowledgeRelations.filter(relation=>!(relation.sourceType==='experience'&&String(relation.sourceId)===String(experienceId)));knowledgeRelations.push(...(payload.data||[]));return payload.data||[]}
async function removeKnowledgeRelationsFor(type,id){const matches=knowledgeRelations.filter(relation=>relationOtherSide(relation,type,id));if(!matches.length)return;await Promise.all(matches.map(relation=>knowledgeRequest(`/api/knowledge/relations/${encodeURIComponent(relation.id)}`,{method:'DELETE',headers:{'X-Request-Id':requestId()}}).catch(()=>null)));const ids=new Set(matches.map(relation=>String(relation.id)));knowledgeRelations=knowledgeRelations.filter(relation=>!ids.has(String(relation.id)))}
function renderRelationLinks(label,entries){if(!entries.length)return'';const visible=entries.slice(0,3);return`<div class="zx-knowledge-rel-group"><div class="zx-knowledge-rel-title">${esc(label)} <span>${entries.length}</span></div><div class="zx-knowledge-rel-links">${visible.map(entry=>`<button type="button" class="zx-knowledge-rel-link" data-preview-knowledge="${attr(knowledgeRef(entry.type,entry.id))}">${esc(knowledgeItemTitle(entry.type,entry.item))}</button>`).join('')}${entries.length>3?`<span class="zx-knowledge-rel-more">查看全部 ${entries.length} 条</span>`:''}</div></div>`}
function renderKnowledgeRelations(type,item){const id=knowledgeItemId(type,item),normalized=normalizeKnowledgeType(type);if(normalized==='experience')return`<div class="zx-knowledge-relations">${renderRelationLinks('关联常用话术',relatedKnowledge(normalized,id,'script'))}${renderRelationLinks('关联资料',relatedKnowledge(normalized,id,'material'))}</div>`;return`<div class="zx-knowledge-relations">${renderRelationLinks('关联经验总结',relatedKnowledge(normalized,id,'experience'))}</div>`}
function captureKnowledgeEditorDraft(){if(modalState?.type!=='knowledge')return null;const form=$('#knowledgeForm');if(!form)return null;const fields=formObject(form);return{knowledgeType:modalState.knowledgeType,normalized:modalState.knowledgeNormalizedType,id:modalState.id,editing:modalState.editing,fields,selectedScripts:$$('input[name="knowledgeLink_script"]:checked',form).map(input=>input.value),selectedMaterials:$$('input[name="knowledgeLink_material"]:checked',form).map(input=>input.value)}}
function restoreKnowledgeEditorDraft(){const draft=knowledgePreviewReturn;if(!draft)return;const item=draft.editing?knowledgeItem(draft.normalized,draft.id):null;knowledgePreviewReturn=null;knowledgePreviewHistory=[];knowledgeForm(draft.knowledgeType,item);const form=$('#knowledgeForm');if(!form)return;Object.entries(draft.fields||{}).forEach(([name,value])=>{const input=form.elements.namedItem(name);if(input&&'value'in input)input.value=value});const selected=new Set([...(draft.selectedScripts||[]),...(draft.selectedMaterials||[])]);$$('input[name^="knowledgeLink_"]',form).forEach(input=>{input.checked=selected.has(input.value)})}
function renderKnowledgePicker(targetType,selectedIds=[]){const type=normalizeKnowledgeType(targetType),items=knowledgeItems(knowledgeStateKey(type)),selected=new Set(selectedIds.map(String)),label=type==='script'?'常用话术':'资料库';return`<div class="zx-knowledge-picker"><label>${type==='script'?'关联常用话术':'关联资料库'}</label><input type="search" class="zx-input" data-knowledge-link-search="${type}" placeholder="${type==='script'?'搜索话术标题、分类或内容……':'搜索资料名称、分类或文件类型……'}"><div class="zx-knowledge-picker-list" data-knowledge-link-options="${type}">${items.length?items.map(item=>{const id=knowledgeItemId(type,item),search=[knowledgeItemTitle(type,item),item.category,item.content,item.description,item.extension].join(' ').toLowerCase();return`<label class="zx-knowledge-picker-option" data-knowledge-search-text="${attr(search)}"><input type="checkbox" name="knowledgeLink_${type}" value="${attr(id)}" ${selected.has(id)?'checked':''}><span><b>${esc(knowledgeItemTitle(type,item))}</b><small>${esc(item.category||label)}</small></span><button type="button" class="zx-btn ghost small" data-preview-knowledge="${attr(knowledgeRef(type,id))}">预览</button></label>`}).join(''):`<div class="zx-empty">暂无可关联的${label}</div>`}</div></div>`}
function renderPreviewRelationGroups(type,id){const normalized=normalizeKnowledgeType(type);if(normalized==='experience')return`${renderRelationLinks('关联常用话术',relatedKnowledge(normalized,id,'script'))}${renderRelationLinks('关联资料',relatedKnowledge(normalized,id,'material'))}`;return renderRelationLinks('关联经验总结',relatedKnowledge(normalized,id,'experience'))}
function spreadsheetMerge(preview,rowNumber,columnIndex){return(preview.merges||[]).find(merge=>rowNumber>=merge.startRow&&rowNumber<=merge.endRow&&columnIndex>=merge.startColumn&&columnIndex<=merge.endColumn)}
function renderSpreadsheetPreview(preview){const rows=preview.rows||[],columns=preview.columns||[];return`<div class="zx-sheet-toolbar"><span>工作表：</span>${(preview.sheets||[]).map(sheet=>`<button class="zx-btn small ${sheet===preview.activeSheet?'active':''}" data-material-preview-sheet="${attr(sheet)}">${esc(sheet)}</button>`).join('')}</div><div class="zx-sheet-wrap"><table class="zx-sheet-table"><thead><tr><th class="zx-sheet-corner">#</th>${columns.map(column=>`<th>${esc(column)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><th>${row.rowNumber}</th>${(row.cells||[]).map((cell,index)=>{const merge=spreadsheetMerge(preview,row.rowNumber,index);if(merge&&(row.rowNumber!==merge.startRow||index!==merge.startColumn))return'';const rowspan=merge?Math.max(1,merge.endRow-merge.startRow+1):1,colspan=merge?Math.max(1,Math.min(columns.length-merge.startColumn,merge.endColumn-merge.startColumn+1)):1;return`<td${rowspan>1?` rowspan="${rowspan}"`:''}${colspan>1?` colspan="${colspan}"`:''}>${esc(cell)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="zx-sheet-meta"><span>当前展示 ${preview.offset+1}-${Math.min(preview.offset+rows.length,preview.totalRows)} 行 / 共 ${preview.totalRows} 行${preview.totalColumns>preview.maxColumns?`，前 ${preview.maxColumns} 列 / 共 ${preview.totalColumns} 列`:''}</span>${preview.partial?'<span class="zx-badge orange">当前为部分预览</span>':''}<div>${preview.offset>0?'<button class="zx-btn small" data-material-preview-offset="prev">上一页</button>':''}${preview.offset+rows.length<preview.totalRows?'<button class="zx-btn small" data-material-preview-offset="next">下一页</button>':''}</div></div>`}
function renderMaterialPreviewArea(preview){if(!preview)return'<div class="zx-empty">正在读取资料预览…</div>';if(preview.kind==='spreadsheet')return renderSpreadsheetPreview(preview);if(preview.kind==='text')return`<pre class="zx-knowledge-preview-text">${esc(preview.content||'')}</pre>${preview.partial?'<div class="zx-alert warning">当前为部分预览，可下载原文件查看完整内容。</div>':''}`;if(preview.kind==='image')return`<div class="zx-material-image-preview"><img src="${attr(preview.dataUrl||'')}" alt="${attr(preview.fileName||'资料图片')}"></div>`;return`<div class="zx-empty"><strong>暂不支持在线预览</strong>${esc(preview.error||preview.message||'可下载原文件查看。')}</div>`}
async function fetchMaterialPreview(materialId,sheet='',offset=0){const params=new URLSearchParams({offset:String(offset),limit:'200'});if(sheet)params.set('sheet',sheet);return knowledgeRequest(`/api/materials/${encodeURIComponent(materialId)}/preview?${params}`)}
function knowledgePreviewBody(type,item,preview=null){const normalized=normalizeKnowledgeType(type),id=knowledgeItemId(normalized,item),meta=`<div class="zx-knowledge-preview-meta"><span class="zx-badge">${esc(normalized==='script'?'常用话术':normalized==='experience'?'经验总结':'资料库')}</span><span>${esc(item.category||'未分类')}</span><span>${textDate(item.updatedAt||item.updated_at||item.createdAt||item.created_at)}</span></div>`;const relation=`<div class="zx-knowledge-preview-relations">${renderPreviewRelationGroups(normalized,id)||'<div class="zx-list-meta">暂未关联其他内容</div>'}</div>`;if(normalized==='material')return`${meta}<div class="zx-knowledge-preview-file"><h3>${esc(knowledgeItemTitle(normalized,item))}</h3><div class="zx-info-grid"><div class="zx-info"><label>文件类型</label><div>${esc(String(item.extension||preview?.extension||'文件').toUpperCase())}</div></div><div class="zx-info"><label>文件大小</label><div>${formatBytes(item.size_bytes||item.size||preview?.sizeBytes||0)}</div></div></div>${renderMaterialPreviewArea(preview)}</div>${relation}`;return`${meta}<div class="zx-knowledge-preview-content"><h3>${esc(knowledgeItemTitle(normalized,item))}</h3>${item.scene?`<div class="zx-alert">关联场景：${esc(item.scene)}</div>`:''}<div class="zx-knowledge-preview-copy">${esc(item.content||item.description||'')}</div></div>${relation}`}
async function openKnowledgePreview(type,id,pushHistory=true,sheet='',offset=0){const normalized=normalizeKnowledgeType(type),item=knowledgeItem(normalized,id);if(!item)return toast('关联内容不存在或已被删除','error');const ref=knowledgeRef(normalized,knowledgeItemId(normalized,item));if(pushHistory){if(modalState?.type==='knowledge-preview'&&modalState.ref!==ref)knowledgePreviewHistory.push(modalState.ref);else if(modalState?.type==='knowledge'){knowledgePreviewReturn=captureKnowledgeEditorDraft();knowledgePreviewHistory=[]}else if(modalState?.type!=='knowledge-preview'){knowledgePreviewReturn=null;knowledgePreviewHistory=[]}}modalState={type:'knowledge-preview',ref,previewType:normalized,previewId:knowledgeItemId(normalized,item),sheet,offset,preview:null};const back=knowledgePreviewHistory.length||knowledgePreviewReturn?`<button class="zx-btn" data-action="knowledge-preview-back">${knowledgePreviewHistory.length?'← 返回上一内容':'← 返回编辑'}</button>`:'';const actions=`${normalized==='script'?'<button class="zx-btn" data-action="copy-preview-knowledge">复制话术</button>':''}${normalized==='material'&&item.serverId?`<button class="zx-btn primary" data-material-download="${attr(item.serverId)}">下载原文件</button>`:''}<button class="zx-btn" data-action="open-full-knowledge">打开完整详情</button><button class="zx-btn" data-action="close-modal">关闭</button>`;modal(`${normalized==='script'?'常用话术':normalized==='experience'?'经验总结':'资料预览'} · ${esc(knowledgeItemTitle(normalized,item))}`,knowledgePreviewBody(normalized,item),`<div class="zx-preview-foot-nav">${back}</div><div class="zx-actions">${actions}</div>`,true,false,'zx-knowledge-preview-modal');if(normalized==='material'&&item.serverId){try{const preview=await fetchMaterialPreview(item.serverId,sheet,offset);if(modalState?.type!=='knowledge-preview'||modalState.ref!==ref)return;modalState.preview=preview;modalState.sheet=preview.activeSheet||sheet;modalState.offset=Number(preview.offset||0);modal(`${normalized==='script'?'常用话术':normalized==='experience'?'经验总结':'资料预览'} · ${esc(knowledgeItemTitle(normalized,item))}`,knowledgePreviewBody(normalized,item,preview),`<div class="zx-preview-foot-nav">${back}</div><div class="zx-actions">${actions}</div>`,true,false,'zx-knowledge-preview-modal')}catch(error){if(modalState?.type!=='knowledge-preview'||modalState.ref!==ref)return;modal(`${'资料预览'} · ${esc(knowledgeItemTitle(normalized,item))}`,knowledgePreviewBody(normalized,item,{kind:'unsupported',error:error.message}),`<div class="zx-preview-foot-nav">${back}</div><div class="zx-actions">${actions}</div>`,true,false,'zx-knowledge-preview-modal')}}}
function knowledgePreviewBack(){const ref=knowledgePreviewHistory.pop();if(ref){const parsed=parseKnowledgeRef(ref);openKnowledgePreview(parsed.type,parsed.id,false);return}restoreKnowledgeEditorDraft()}

function materialConversionOptions(item){
 const ext=String(item.extension||item.name||'').split('.').pop().toLowerCase();
 if(!STABLE_MATERIAL_FORMATS.includes(ext))return '';
 const id=attr(item.serverId||item.id);
 return `<div class="zx-material-convert"><select class="zx-material-convert-select" data-material-format="${id}" data-material-convert="${id}" aria-label="转换格式并下载"><option value="">转换格式并下载</option>${STABLE_MATERIAL_FORMATS.filter(x=>x!==ext).map(x=>`<option value="${x}">${x.toUpperCase()}</option>`).join('')}</select></div>`;
}
function materialCard(item){
 const server=!!item.serverId||!!item.download_url;
 const ext=String(item.extension||item.name||'').split('.').pop().toLowerCase();
 const canExecute=['exe','apk'].includes(ext),id=knowledgeItemId('material',item);
 return `<article class="zx-card zx-knowledge-card zx-material-card" id="zx-k-${attr(item.id)}"><span class="zx-badge" style="align-self:flex-start;margin-bottom:10px">${esc(item.category||'资料文件')}</span><button type="button" class="zx-knowledge-title-button" data-preview-knowledge="${attr(knowledgeRef('material',id))}"><h3>${esc(knowledgeItemTitle('material',item))}</h3></button><p>${esc(item.content||item.description||`${String(ext||'文件').toUpperCase()} · ${formatBytes(item.size_bytes||item.size||0)}`)}</p>${renderKnowledgeRelations('material',item)}<div class="zx-card-foot"><span>${textDate(item.updatedAt||item.createdAt||item.created_at)}</span><div class="zx-material-actions">${server?`<button class="zx-btn ghost small" data-preview-knowledge="${attr(knowledgeRef('material',id))}">预览</button><button class="zx-btn ghost small" data-material-download="${attr(item.serverId||item.id)}">下载原文件</button>${materialConversionOptions(item)}`:''}${canExecute?`<button class="zx-btn small" data-material-execute="${attr(item.serverId||item.id)}">申请安全执行</button>`:''}<button class="zx-btn danger small" data-delete-knowledge="materials:${attr(item.id)}">删除</button></div></div></article>`;
}
function knowledgeViewMode(){return state.settings?.knowledgeView==='list'?'list':'card'}
function materialCategoryNames(){const cats=state.settings.materialCategories||[];return cats.length?[...new Set(cats)].filter(Boolean):[...DEFAULT_MATERIAL_CATEGORIES]}
function sortKnowledgeLabels(labels){return labels.map((name,index)=>({name,index,length:Array.from(String(name)).length})).sort((a,b)=>a.length-b.length||a.index-b.index).map(item=>item.name)}
function renderMaterialCategories(active){const selected=selectedFilterValues(active);return `<div class="zx-material-categories">${['全部',...sortKnowledgeLabels(materialCategoryNames())].map(name=>`<button class="zx-btn small ${name==='全部'?!selected.length?'active':'':selected.includes(name)?'active':''}" data-material-category="${attr(name)}">${esc(name)}</button>`).join('')}</div>`}
function knowledgeCategoryNames(items,type=''){const itemCategories=items.map(item=>String(item.category||'').trim()||'未分类');const configured=type==='experiences'?(state.settings.experienceCategories||[]):type==='scripts'?(state.settings.scriptCategories||[]):[];return [...new Set([...configured,...itemCategories].map(name=>String(name).trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function renderKnowledgeCategories(active,items,hideLabel=false,type=''){const selected=selectedFilterValues(active);return `<div class="zx-knowledge-categories">${hideLabel?'':`<span class="zx-list-meta">分类</span>`}${['全部',...sortKnowledgeLabels(knowledgeCategoryNames(items,type))].map(name=>`<button class="zx-btn small ${name==='全部'?!selected.length?'active':'':selected.includes(name)?'active':''}" data-knowledge-category="${attr(name)}">${esc(name)}</button>`).join('')}</div>`}
function scriptCategoryNames(){return knowledgeCategoryNames(state.scripts,'scripts').filter(name=>name!=='未分类')}
function scriptCategorySettings(){const categories=scriptCategoryNames();modalState={type:'script-categories'};modal('常用话术自定义标签',`<div class="zx-alert">新增常用话术时可选择自定义标签，常用话术会按标签分类显示。</div><div class="zx-toolbar"><input class="zx-input" id="newScriptCategoryName" maxlength="50" placeholder="新增自定义标签"><button class="zx-btn primary" data-action="add-script-category">添加标签</button></div><div class="zx-list">${categories.length?categories.map(name=>{const used=state.scripts.filter(item=>String(item.category||'').trim()===name).length;return `<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(name)}</div><div class="zx-list-meta">自定义标签 · ${used} 条话术</div></div><button class="zx-btn danger small" data-delete-script-category="${attr(name)}">删除</button></div>`}).join(''):'<div class="zx-empty">暂无自定义标签</div>'}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true)}
function addScriptCategory(){const input=$('#newScriptCategoryName');const name=input?.value.trim();if(!name)return toast('请输入标签名称','error');if(name.length>50)return toast('标签名称不能超过 50 个字符','error');if(scriptCategoryNames().includes(name))return toast('该标签已存在','error');state.settings.scriptCategories=[...(state.settings.scriptCategories||[]),name];save('话术标签已添加');render();scriptCategorySettings()}
function deleteScriptCategory(name){const used=state.scripts.filter(item=>String(item.category||'').trim()===name).length;if(used)return toast(`该标签下还有 ${used} 条话术，暂不能删除`,'error');state.settings.scriptCategories=(state.settings.scriptCategories||[]).filter(item=>item!==name);save('话术标签已删除');render();scriptCategorySettings()}
function experienceCategoryNames(){return knowledgeCategoryNames(state.experiences,'experiences').filter(name=>name!=='未分类')}
function experienceCategorySettings(){const categories=experienceCategoryNames();modalState={type:'experience-categories'};modal('经验总结自定义标签',`<div class="zx-alert">新增经验总结时可选择自定义标签，经验总结会按标签分类显示。</div><div class="zx-toolbar"><input class="zx-input" id="newExperienceCategoryName" maxlength="50" placeholder="新增自定义标签"><button class="zx-btn primary" data-action="add-experience-category">添加标签</button></div><div class="zx-list">${categories.length?categories.map(name=>{const used=state.experiences.filter(item=>String(item.category||'').trim()===name).length;return `<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(name)}</div><div class="zx-list-meta">自定义标签 · ${used} 条经验</div></div><button class="zx-btn danger small" data-delete-experience-category="${attr(name)}">删除</button></div>`}).join(''):'<div class="zx-empty">暂无自定义标签</div>'}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true)}
function addExperienceCategory(){const input=$('#newExperienceCategoryName');const name=input?.value.trim();if(!name)return toast('请输入标签名称','error');if(name.length>50)return toast('标签名称不能超过 50 个字符','error');if(experienceCategoryNames().includes(name))return toast('该标签已存在','error');state.settings.experienceCategories=[...(state.settings.experienceCategories||[]),name];save('经验标签已添加');render();experienceCategorySettings()}
function deleteExperienceCategory(name){const used=state.experiences.filter(item=>String(item.category||'').trim()===name).length;if(used)return toast(`该标签下还有 ${used} 条经验，暂不能删除`,'error');state.settings.experienceCategories=(state.settings.experienceCategories||[]).filter(item=>item!==name);save('经验标签已删除');render();experienceCategorySettings()}
function materialCategorySettings(){const categories=materialCategoryNames();modalState={type:'material-categories'};modal('资料库自定义标签',`<div class="zx-toolbar"><input class="zx-input" id="newMaterialCategoryName" maxlength="50" placeholder="新增自定义标签"><button class="zx-btn primary" data-action="add-material-category">添加标签</button></div><div class="zx-list">${categories.map(name=>{const builtIn=DEFAULT_MATERIAL_CATEGORIES.includes(name);const used=state.materials.filter(item=>(item.category||'资料文件')===name).length;return `<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(name)}</div><div class="zx-list-meta">${builtIn?'系统标签':'自定义标签'} · ${used} 份资料</div></div><button class="zx-btn danger small" data-delete-material-category="${attr(name)}">删除</button></div>`}).join('')}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true)}
function addMaterialCategory(){const input=$('#newMaterialCategoryName');const name=input?.value.trim();if(!name)return toast('请输入标签名称','error');if(name.length>50)return toast('标签名称不能超过 50 个字符','error');if(materialCategoryNames().includes(name))return toast('该标签已存在','error');state.settings.materialCategories=[...(state.settings.materialCategories||[]),name];save('资料标签已添加');render();materialCategorySettings()}
function deleteMaterialCategory(name){if(state.materials.some(item=>(item.category||'资料文件')===name))return toast('该标签下有资料正在使用，无法删除','error');state.settings.materialCategories=(state.settings.materialCategories||[]).filter(item=>item!==name);save('资料标签已删除');render();materialCategorySettings()}
function renderKnowledge(){
 const type=query().get('type')||'scripts',items=knowledgeItems(type),titles={scripts:'常用话术',experiences:'经验总结',materials:'资料库'},view=knowledgeViewMode();
 const category=selectedFilterValues((query().get('categories')||query().get('category')||'').split(',')),categories=materialCategoryNames();
 const fallbackCategory=type==='materials'?'资料文件':'未分类';
 const visibleItems=!category.length?items:items.filter(item=>category.includes(item.category||fallbackCategory));
 const materialUpload=type==='materials'?`<div class="zx-upload zx-material-toolbar-upload" id="materialsDropzone" data-pet-guide-action="upload-materials" tabindex="0" role="button" aria-label="拖拽或选择资料上传"><input type="file" id="materialsUpload" multiple accept=".doc,.docx,.xls,.xlsx,.ppt,.pptx,.pdf,.txt,.jpg,.jpeg,.png,.gif,.svg,.psd,.mp3,.wav,.mp4,.zip,.rar,.exe,.apk,.csv,.json,.md,.rtf,.html"><label for="materialsUpload" class="zx-btn primary small">上传资料</label><span id="materialsUploadStatus" class="zx-list-meta">拖拽或本地上传</span><select class="zx-select small" id="materialCategory" aria-label="资料分类">${categories.map(name=>`<option value="${attr(name)}">${esc(name)}</option>`).join('')}</select></div>`:'';
 const materialTools=type==='materials'?renderMaterialCategories(category):'';
 const cards=visibleItems.length?visibleItems.map(item=>{if(type==='materials')return materialCard(item);const normalized=normalizeKnowledgeType(type),id=knowledgeItemId(normalized,item);return`<article class="zx-card zx-knowledge-card ${normalized==='experience'?'zx-experience-card':''}" id="zx-k-${attr(item.id)}"><span class="zx-badge" style="align-self:flex-start;margin-bottom:10px">${esc(item.category||titles[type])}</span><button type="button" class="zx-knowledge-title-button" data-preview-knowledge="${attr(knowledgeRef(normalized,id))}"><h3>${esc(knowledgeItemTitle(normalized,item))}</h3></button><p>${esc(item.content||item.description||item.url||'')}</p>${renderKnowledgeRelations(normalized,item)}<div class="zx-card-foot"><span>${textDate(item.updatedAt||item.createdAt)}</span><div><button class="zx-btn ghost small" data-preview-knowledge="${attr(knowledgeRef(normalized,id))}">预览</button>${normalized==='experience'?`<button class="zx-btn ghost small" data-edit-knowledge="${attr(id)}">编辑</button>`:''}<button class="zx-btn ghost small" data-copy-knowledge="${type}:${item.id}">复制</button><button class="zx-btn danger small" data-delete-knowledge="${type}:${item.id}">删除</button></div></div></article>`}).join(''):`<div class="zx-empty" style="grid-column:1/-1"><strong>暂无${titles[type]}</strong>${type==='materials'?'上传资料后会在这里集中管理。':'将实用内容沉淀到经验中心，客户沟通时可以快速调用'}</div>`;
 const categorySettingsButton=type==='materials'?'<button class="zx-btn primary small" data-action="material-category-settings">自定义标签</button>':type==='experiences'?'<button class="zx-btn primary small" data-action="experience-category-settings">自定义标签</button>':type==='scripts'?'<button class="zx-btn primary small" data-action="script-category-settings">自定义标签</button>':'';
 const newKnowledgeButton=type==='scripts'?'<button class="zx-btn primary small" data-new-knowledge="scripts">新增常用话术</button>':type==='experiences'?'<button class="zx-btn primary small" data-new-knowledge="experiences">新增经验总结</button>':'';
 const viewSwitch=`<div class="zx-knowledge-view-switch" role="group" aria-label="内容展示方式"><span>展示方式</span><button class="zx-btn small ${view==='card'?'active':''}" data-knowledge-view="card" aria-pressed="${view==='card'}">▦ 卡片视图</button><button class="zx-btn small ${view==='list'?'active':''}" data-knowledge-view="list" aria-pressed="${view==='list'}">☰ 列表视图</button>${categorySettingsButton}${newKnowledgeButton}</div>`;
 return shell(`<section class="zx-card"><div class="zx-tabs"><button class="zx-tab ${type==='scripts'?'active':''}" data-knowledge-tab="scripts">常用话术 <span class="count">${state.scripts.length}</span></button><button class="zx-tab ${type==='experiences'?'active':''}" data-knowledge-tab="experiences">经验总结 <span class="count">${state.experiences.length}</span></button><button class="zx-tab ${type==='materials'?'active':''}" data-knowledge-tab="materials">资料库 <span class="count">${state.materials.length}</span></button></div><div class="zx-knowledge-toolbar ${type==='materials'?'is-materials':''}">${materialUpload}${viewSwitch}</div><div class="zx-card-body">${type==='materials'?materialTools:renderKnowledgeCategories(category,items,true,type)}<div class="zx-grid zx-knowledge-grid ${view==='list'?'is-list':''}">${cards}</div></div></section>`);
}
function formatBytes(bytes){const n=Number(bytes)||0;if(!n)return '大小未知';if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;if(n<1024*1024*1024)return `${(n/1024/1024).toFixed(1)} MB`;return `${(n/1024/1024/1024).toFixed(1)} GB`}
async function loadMaterials(){
 if(materialsHydrating||!window.ZhiXunAuth?.getToken())return;materialsHydrating=true;
 try{const resp=await fetch('/api/materials',{headers:{Authorization:`Bearer ${window.ZhiXunAuth.getToken()}`}});if(!resp.ok)return;const payload=await resp.json();const remote=(payload.data||[]).map(row=>({...row,serverId:row.id,id:`server_${row.id}`,title:row.original_name,category:row.category||'资料文件',description:`${String(row.extension||'文件').toUpperCase()} · ${formatBytes(row.size_bytes)}`,createdAt:row.created_at}));state.settings.materialCategories=[...new Set([...(state.settings.materialCategories||[]),...remote.map(row=>row.category).filter(Boolean)])];const local=state.materials.filter(x=>!x.serverId&&!x.download_url);state.materials=[...remote,...local];save();await loadKnowledgeRelations(false);render();}catch(err){/* Sync failed silently; materials will retry on next navigation */}finally{materialsHydrating=false}
}
async function uploadMaterials(files){
 const status=$('#materialsUploadStatus');if(!files.length)return;const valid=Array.from(files).filter(f=>f.size<=800*1024*1024);if(valid.length!==files.length)toast('已跳过超过 800MB 的文件','error');if(!valid.length)return;const data=new FormData();valid.slice(0,10).forEach(f=>data.append('files',f));data.append('category',$('#materialCategory')?.value||'资料文件');if(status)status.textContent='正在上传…';try{const resp=await fetch('/api/materials/upload',{method:'POST',headers:{Authorization:`Bearer ${window.ZhiXunAuth?.getToken()||''}`},body:data});const payload=await resp.json();if(!resp.ok)throw new Error(payload.error||'上传失败');toast(payload.message||'资料已上传','success');state.materials=[...(payload.data||[]).map(row=>({...row,serverId:row.id,id:`server_${row.id}`,title:row.original_name,category:row.category||$('#materialCategory')?.value||'资料文件',description:`${String(row.extension||'文件').toUpperCase()} · ${formatBytes(row.size_bytes)}`,createdAt:row.created_at})),...state.materials.filter(x=>!x.serverId&&!x.download_url)];save();render();}catch(err){toast(err.message||'资料上传失败','error');if(status)status.textContent='上传失败，请重试'}
}
function responseFilename(resp,fallback){const header=resp.headers.get('Content-Disposition')||'';const encoded=header.match(/filename\*=(?:UTF-8'')?([^;]+)/i)?.[1];const plain=header.match(/filename=\"?([^;\"]+)/i)?.[1];try{return decodeURIComponent((encoded||plain||fallback).replace(/^\"|\"$/g,''))}catch(_err){return encoded||plain||fallback}}
async function downloadFullBackup(){try{toast('正在生成完整备份…');const response=await window.ZhiXunAuth.fetch('/api/backups/export');if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'完整备份生成失败')}const blob=await response.blob();downloadBlob(blob,responseFilename(response,`志询运营完整备份_${today()}.zip`));toast('完整备份已下载','success')}catch(error){toast(error.message||'完整备份下载失败','error')}}
function backupRestoreProgressMarkup(){if(!backupRestoreState.visible)return'';const progress=Math.max(0,Math.min(100,Math.round(Number(backupRestoreState.progress)||0))),status=backupRestoreState.error?'error':backupRestoreState.running?'running':'success';return`<section class="zx-backup-restore-progress ${status}" aria-live="polite"><div class="zx-backup-restore-head"><div><strong>${esc(backupRestoreState.phase||'准备导入备份')}</strong><small>${esc(backupRestoreState.fileName||'完整备份')}</small></div><b>${progress}%</b></div><div class="zx-backup-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}" aria-label="备份导入进度"><span style="width:${progress}%"></span></div>${backupRestoreState.error?`<small class="zx-backup-restore-error">${esc(backupRestoreState.error)}</small>`:'<small>上传完成后将由服务器校验并恢复，完成前不会覆盖现有数据。</small>'}</section>`}
function updateBackupRestoreProgress(patch){backupRestoreState={...backupRestoreState,...patch,visible:true};const panel=$('.zx-backup-restore-progress');if(!panel){if(route()==='settings'&&settingsTab==='data')render();return}const progress=Math.max(0,Math.min(100,Math.round(Number(backupRestoreState.progress)||0))),title=panel.querySelector('strong'),file=panel.querySelector('.zx-backup-restore-head small'),value=panel.querySelector('.zx-backup-restore-head b'),bar=panel.querySelector('.zx-backup-progress-track span'),track=panel.querySelector('.zx-backup-progress-track');if(title)title.textContent=backupRestoreState.phase||'准备导入备份';if(file)file.textContent=backupRestoreState.fileName||'完整备份';if(value)value.textContent=`${progress}%`;if(bar)bar.style.width=`${progress}%`;if(track)track.setAttribute('aria-valuenow',String(progress))}
function scheduleBackupRestoreProgressClose(){if(backupRestoreHideTimer)clearTimeout(backupRestoreHideTimer);const completedFileName=backupRestoreState.fileName;backupRestoreHideTimer=setTimeout(()=>{backupRestoreHideTimer=null;if(backupRestoreState.running||backupRestoreState.error||Number(backupRestoreState.progress)<100||backupRestoreState.fileName!==completedFileName)return;backupRestoreState={...backupRestoreState,visible:false};$('.zx-backup-restore-progress')?.remove()},1500)}
function backupRestoreStorageKey(){return`zhixun:full-backup-restore:${currentUser()?.id??'unknown'}`}
function rememberFullBackupRestore(value){try{if(value)localStorage.setItem(backupRestoreStorageKey(),JSON.stringify(value));else localStorage.removeItem(backupRestoreStorageKey())}catch(_){}}
function uploadFullBackupFile(file,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),body=new FormData(),jobId=`full-backup-restore-${requestId()}`;body.append('backup',file);xhr.open('POST','/api/backups/restore');const token=window.ZhiXunAuth?.getToken?.();if(token)xhr.setRequestHeader('Authorization',`Bearer ${token}`);xhr.setRequestHeader('X-Request-Id',jobId);xhr.upload.addEventListener('progress',event=>{if(event.lengthComputable&&event.total>0)onProgress(Math.min(90,event.loaded/event.total*90));else onProgress(5)});xhr.upload.addEventListener('load',()=>onProgress(92));xhr.addEventListener('load',()=>{let data={};try{data=JSON.parse(xhr.responseText||'{}')}catch(_){}if(xhr.status===401){window.ZhiXunAuth?.clearSession?.();window.location.href='/login.html';return reject(new Error('未授权，请重新登录'))}if(xhr.status>=200&&xhr.status<300)return resolve({...data,jobId:data.jobId||jobId});const error=new Error(data.error||`完整备份上传失败（${xhr.status||'网络异常'}），原数据未修改`);error.status=xhr.status;reject(error)});xhr.addEventListener('error',()=>reject(new Error('备份上传失败，请检查网络或服务器')));xhr.addEventListener('abort',()=>reject(new Error('备份上传已取消')));xhr.send(body)})}
async function waitForFullBackupRestore(jobId,fileName){while(true){const status=await syncFetch(`/api/sync/jobs/${encodeURIComponent(jobId)}`);if(status.status==='completed')return status;if(status.status==='failed'){const error=new Error(status.lastError||'完整备份恢复失败，原数据未修改');error.retryable=false;throw error}const completed=Number(status.completedBatches||0),total=Math.max(1,Number(status.totalBatches||1)),progress=Math.max(93,Math.min(98,93+Math.round(completed/total*5)));updateBackupRestoreProgress({phase:'服务端已持久化，后台正在校验并恢复',progress});await waitForSyncRetry(500)}}
async function finishFullBackupRestore(jobId,fileName){const status=await waitForFullBackupRestore(jobId,fileName);updateBackupRestoreProgress({phase:'正在读取恢复后的数据',progress:99});const snapshot=await syncFetch('/api/sync/snapshot');if(!snapshot?.state)throw new Error('备份已恢复，但未能读取最新服务器数据，请刷新页面');applyIncomingSnapshot(snapshot,{forceReset:true});pendingBackupImport=null;rememberFullBackupRestore(null);backupRestoreState={visible:true,running:false,phase:'备份导入完成',progress:100,fileName,error:''};loadKnowledgeRelations(true);loadDataPermissions(true);loadPriorityCustomers(true);render();scheduleBackupRestoreProgressClose();operationNotice(`backup:${jobId}`,`完整备份已恢复${status.restoredFiles?`，包含 ${status.restoredFiles} 个文件`:''}`,'success')}
async function restoreFullBackupFile(file){if(!currentUserIsAdmin())throw new Error('只有管理员可以恢复完整备份');if(backupRestoreState.running)throw new Error('已有备份正在导入，请等待当前任务完成');if(!window.confirm('恢复完整备份会用压缩包中的工作区、资料、客户附件和关联数据替换当前团队数据。系统会先完整校验，失败时不会修改现有数据。确定继续吗？'))return;if(backupRestoreHideTimer){clearTimeout(backupRestoreHideTimer);backupRestoreHideTimer=null}backupRestoreState={visible:true,running:true,phase:'正在上传备份',progress:0,fileName:file.name,error:''};render();try{const data=await uploadFullBackupFile(file,progress=>updateBackupRestoreProgress({phase:progress>=92?'正在提交任务到服务端':'正在上传备份',progress}));if(!data.serverPersisted||!data.jobId)throw new Error('服务端未确认备份任务已持久化，请重试');localSyncOperationIds.add(String(data.jobId));rememberFullBackupRestore({jobId:data.jobId,fileName:file.name});updateBackupRestoreProgress({phase:'服务端已持久化，后台正在校验并恢复',progress:93});await finishFullBackupRestore(data.jobId,file.name)}catch(error){if(backupRestoreHideTimer){clearTimeout(backupRestoreHideTimer);backupRestoreHideTimer=null}rememberFullBackupRestore(null);backupRestoreState={visible:true,running:false,phase:'备份导入失败，原数据未修改',progress:0,fileName:file.name,error:error.message||'完整备份恢复失败'};render();throw error}}
async function resumeFullBackupRestore(){let pending=null;try{pending=JSON.parse(localStorage.getItem(backupRestoreStorageKey())||'null')}catch(_){}if(!pending?.jobId||backupRestoreState.running)return;localSyncOperationIds.add(String(pending.jobId));backupRestoreState={visible:true,running:true,phase:'正在读取服务端持久化任务',progress:93,fileName:pending.fileName||'完整备份',error:''};if(route()==='settings')render();try{await finishFullBackupRestore(pending.jobId,pending.fileName||'完整备份')}catch(error){rememberFullBackupRestore(null);backupRestoreState={visible:true,running:false,phase:'备份导入失败，原数据未修改',progress:0,fileName:pending.fileName||'完整备份',error:error.message||'完整备份恢复失败'};if(route()==='settings')render();operationNotice(`backup:${pending.jobId}`,backupRestoreState.error,'error')}}
setTimeout(resumeFullBackupRestore,1000);
async function downloadMaterial(id){try{const resp=await fetch(`/api/materials/${encodeURIComponent(id)}/download`,{headers:{Authorization:`Bearer ${window.ZhiXunAuth?.getToken()||''}`}});if(!resp.ok)throw new Error('资料下载失败');const blob=await resp.blob();downloadBlob(blob,responseFilename(resp,`资料_${id}`));}catch(err){toast(err.message||'资料下载失败','error')}}
async function convertMaterial(id){const select=document.querySelector(`[data-material-format=\"${CSS.escape(String(id))}\"]`);const target=select?.value;if(!target)return toast('请先选择转换格式','error');try{const resp=await fetch(`/api/materials/${encodeURIComponent(id)}/convert`,{method:'POST',headers:{Authorization:`Bearer ${window.ZhiXunAuth?.getToken()||''}`,'Content-Type':'application/json'},body:JSON.stringify({target_format:target})});const contentType=resp.headers.get('Content-Type')||'';if(resp.ok&&resp.headers.get('Content-Disposition')){const blob=await resp.blob();downloadBlob(blob,responseFilename(resp,`资料_${id}.${target}`));toast(`已转换为 ${target.toUpperCase()} 并下载`,'success');return}const data=await resp.json().catch(()=>({}));if(data.status==='original_only'){toast(data.message||'该格式无法稳定转换，已下载原文件','');return downloadMaterial(id)}if(!resp.ok)throw new Error(data.error||'资料转换失败');toast(data.message||'资料转换任务已提交','success');}catch(err){toast(err.message||'资料转换失败','error')}}
async function executeMaterial(id){try{const resp=await fetch(`/api/materials/${encodeURIComponent(id)}/execute`,{method:'POST',headers:{Authorization:`Bearer ${window.ZhiXunAuth?.getToken()||''}`}});const data=await resp.json();toast(data.message||'当前未配置安全执行沙箱',resp.status===503?'':'error');}catch(err){toast(err.message||'执行申请失败','error')}}
async function deleteRemoteMaterial(id){try{const resp=await fetch(`/api/materials/${encodeURIComponent(id)}`,{method:'DELETE',headers:{Authorization:`Bearer ${window.ZhiXunAuth?.getToken()||''}`}});const data=await resp.json();if(!resp.ok)throw new Error(data.error||'删除失败');await removeKnowledgeRelationsFor('material',id);state.materials=state.materials.filter(x=>String(x.serverId)!==String(id));save('资料已删除');render();toast(data.message||'资料已删除','success')}catch(err){toast(err.message||'资料删除失败','error')}}
function backupImportPreviewMarkup(){const pending=pendingBackupImport,stats=pending?.plan?.stats;if(!pending||!stats)return'';return`<section class="zx-backup-import-preview"><div class="zx-card-title"><div><h3 style="margin:0">待确认导入备份</h3><small>${esc(pending.fileName)} · 当前不会立即修改数据</small></div></div><div class="zx-backup-import-summary"><span><b>${stats.updated}</b> 位更新</span><span><b>${stats.added}</b> 位新增</span><span><b>${stats.unmatched}</b> 位无法匹配</span></div><small class="zx-list-meta">无法匹配的记录仍会按新增规则导入；备份中的空字段不会覆盖已有信息。</small><div class="zx-actions" style="margin-top:12px"><button type="button" class="zx-btn" data-action="cancel-backup-import">取消</button><button type="button" class="zx-btn primary" data-action="confirm-backup-import">确认导入并同步</button></div></section>`}
function confirmBackupImport(){const pending=pendingBackupImport;if(!pending)return;if(!syncState.ready)return toast('团队同步尚未准备好，请稍后再试','error');const base=cloneData(syncState.base||state),result=mergeBackupData(base,pending.incoming),stats=result.stats,user=currentUser();result.data.dataVersionName=pending.fileName;result.data.logs=[...(result.data.logs||[]),{id:uid('log'),action:'导入完整备份',detail:`更新 ${stats.updated} 位，新增 ${stats.added} 位，无法匹配 ${stats.unmatched} 位`,at:now(),user:user.display_name||user.username,userId:user.id??'',username:user.username||''}];const message=`备份导入完成：更新 ${stats.updated} 位，新增 ${stats.added} 位${stats.unmatched?`，无法匹配 ${stats.unmatched} 位`:''}`,job=createPatchJob('backup',base,result.data,message);if(!job.batches.length){pendingBackupImport=null;render();return toast('备份内容与当前服务端数据一致，无需导入','info')}pendingBackupImport=null;render();queueBatchJob(job,runPatchJob)}
function renderOperationLogs(){const remote=operationLogsState,items=remote.items||[];if(remote.loading&&!remote.loaded)return '<div class="zx-empty"><strong>正在读取操作日志…</strong>请稍候</div>';if(remote.error&&!remote.loaded)return `<div class="zx-empty"><strong>操作日志读取失败</strong>${esc(remote.error)}<button class="zx-btn" data-action="settings-log-retry">重新加载</button></div>`;const list=items.length?items.map(item=>`<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(item.actionLabel||item.action)}</div><div class="zx-list-meta">${esc(item.detail||'团队数据')} · ${esc(item.user||'系统')}</div></div><span>${fmt(item.at)}</span></div>`).join(''):`<div class="zx-empty">${settingsLogScope==='mine'?'暂无自己的操作日志':'暂无操作日志'}</div>`;const pager=`<div class="zx-pager" aria-label="操作日志分页"><span>共 ${remote.total} 条</span><button class="zx-btn small" data-action="settings-log-prev" ${remote.page<=1?'disabled':''}>上一页</button><span>${remote.page} / ${remote.totalPages}</span><button class="zx-btn small" data-action="settings-log-next" ${remote.page>=remote.totalPages?'disabled':''}>下一页</button></div>`;return `${remote.error?`<div class="zx-alert">${esc(remote.error)}</div>`:''}<div class="zx-list">${list}</div>${pager}`}
