restoreContactOverviewAfterCustomerSave=function(context){if(context?.state?.type!=='managed-wechat-combinations'||!context?.detailState?.id)return managedWechatRestoreContactOverviewAfterCustomerSave(context);closeModal();refreshContactOverviewSourceModal(context);modalState={...context.state};pushModalLayer();modalState={...context.detailState};customerDetail(context.detailState.id,detailTab,true);const body=document.querySelector('#'+(context.parentId||'zxModal')+' .zx-modal-body'),results=document.querySelector('#'+(context.parentId||'zxModal')+' #'+(context.resultsId||'managedWechatCombinationResults'));requestAnimationFrame(()=>{if(body)body.scrollTop=context.bodyScrollTop;if(results)results.scrollTop=context.resultsScrollTop});return true};
function injectNationalProvinceOption(selectedProvince=''){const select=document.querySelector('#customerForm [name="province"]');if(select){let option=Array.from(select.options).find(item=>item.value===ALL_PROVINCE);if(!option){option=document.createElement('option');option.value=ALL_PROVINCE;option.textContent=ALL_PROVINCE;select.insertBefore(option,select.options[1]||null)}const current=normalizeProvince(selectedProvince||customerById(modalState?.id)?.province||'');if(current===ALL_PROVINCE)select.value=ALL_PROVINCE}const importSelect=document.getElementById('importUniformProvince');if(importSelect&&!Array.from(importSelect.options).some(item=>item.value===ALL_PROVINCE)){const option=document.createElement('option');option.value=ALL_PROVINCE;option.textContent=ALL_PROVINCE;importSelect.insertBefore(option,importSelect.options[1]||null)}document.querySelectorAll('datalist[id^="zxImportProvs"]').forEach(list=>{if(!Array.from(list.options).some(item=>item.value===ALL_PROVINCE)){const option=document.createElement('option');option.value=ALL_PROVINCE;list.appendChild(option)}})}
const customerFormWithoutNational=customerForm;
customerForm=function(c={}){customerFormWithoutNational(c);injectNationalProvinceOption(c.province||'')};
const nationalProvinceModal=modal;
modal=function(...args){const element=nationalProvinceModal(...args);injectNationalProvinceOption();return element};
function captureCustomerFormTemplate(customer){
 const previousModal=modal,previousState=modalState;let template=null,formState=null;
 modal=function(title,body,foot='',wide=false){template={title,body,foot,wide}};
 try{openStandardCustomerForm(customer);formState=modalState?{...modalState}:null}finally{modal=previousModal;modalState=previousState}
 return template&&formState?{...template,state:formState}:null;
}
function managedWechatEditorCustomer(){return customerById(modalState?.id)||state.captures?.find(item=>String(item.id)===String(modalState?.id))||{}}
function refreshManagedWechatEditorSummary(form){const summary=form?.querySelector('.zx-managed-wechat-editor>summary');if(!summary)return;const values=[...form.querySelectorAll('input[name="managed_wechat_accounts"]:checked')].map(input=>input.value);summary.textContent=values.join('、')||'未分配'}
function injectManagedWechatAccountField(){const form=document.getElementById('customerForm');const editorCustomer=managedWechatEditorCustomer();if(form&&modalState?.id&&!form.querySelector('.zx-managed-wechat-account-field')){const anchor=form.querySelector('[name="wechat_id"]')?.closest('.zx-field');if(anchor){const field=document.createElement('div');field.innerHTML=managedWechatAccountFieldMarkup(editorCustomer);anchor.after(field.firstElementChild)}}const detail=document.querySelector('.zx-customer-detail-modal .zx-info-grid');if(detail&&!detail.querySelector('[data-managed-wechat-account-info]')){const customer=customerById(modalState?.id)||state.captures?.find(item=>String(item.id)===String(modalState?.id));if(customer){const info=document.createElement('div');info.className='zx-info';info.dataset.managedWechatAccountInfo='1';info.innerHTML='<label>管理的微信账户</label><div>'+esc(managedWechatAccountLabel(customer))+'</div>';detail.appendChild(info)}}}
const managedWechatFieldObserver=observeDocumentChanges(()=>injectManagedWechatAccountField());
function injectManagedWechatDedupeField(){document.querySelectorAll('.zx-dedupe-customer').forEach(card=>{if(card.querySelector('[data-managed-wechat-dedupe]'))return;const customer=customerById(card.dataset.dedupeValue);if(!customer)return;const fields=card.querySelector('.zx-dedupe-fields');if(!fields)return;const span=document.createElement('span');span.className='zx-dedupe-field';span.dataset.managedWechatDedupe='1';span.textContent='管理的微信账户：'+managedWechatAccountLabel(customer);fields.appendChild(span)})}
const managedWechatDedupeObserver=observeDocumentChanges(()=>injectManagedWechatDedupeField());
function taskForm(t={}){modalState={type:'task',id:t.id};const types=[...new Set([...(state.taskTypes||DEFAULT_TASK_TYPES),t.type].filter(Boolean))];modal(t.id?'编辑任务':'新建任务',`<form id="taskForm" class="zx-form-grid"><div class="zx-field full"><label>任务标题 ${requiredMark}</label><input class="zx-input" name="title" required value="${attr(t.title||'')}" autofocus></div><div class="zx-field"><label>任务类型</label><select class="zx-select" name="type">${types.map(x=>`<option ${t.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="zx-field"><label>关联客户</label><select class="zx-select" name="customerId"><option value="">不关联客户</option>${officialCustomers().map(c=>`<option value="${c.id}" ${String(t.customerId)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="zx-field"><label>优先级</label><select class="zx-select" name="priority">${['高','中','低'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="zx-field"><label>截止日期</label><input class="zx-input" type="date" name="dueDate" value="${attr((t.dueDate||'').slice(0,10))}"></div><div class="zx-field full"><label>任务说明</label><textarea class="zx-textarea" name="description">${esc(t.description||'')}</textarea></div></form>`,`<button class="zx-btn" data-action="close-modal">取消</button><button class="zx-btn primary" data-action="save-task">保存</button>`)}
function feedbackTypes(){return [...new Set((state.settings.feedbackTypes||[]).filter(Boolean))]}
function feedbackTypeSettings(){modalState={type:'feedback-types'};const types=feedbackTypes();modal('自定义反馈类型',`<div class="zx-alert">反馈类型用于客户反馈分类和筛选。系统预置类型也可以删除；已被反馈使用的类型需要先迁移反馈。</div><div class="zx-toolbar"><input class="zx-input" id="newFeedbackTypeName" maxlength="50" placeholder="新增反馈类型"><button class="zx-btn primary" data-action="add-feedback-type">添加</button></div><div class="zx-list">${types.map(type=>{const used=state.feedback.filter(f=>f.type===type).length;return `<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(type)}</div><div class="zx-list-meta">${used} 条反馈使用中</div></div><button class="zx-btn danger small" data-delete-feedback-type="${attr(type)}">删除</button></div>`}).join('')}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true)}
function addFeedbackType(){const input=$('#newFeedbackTypeName'),name=input?.value.trim();if(!name)return toast('请输入反馈类型','error');if(feedbackTypes().includes(name))return toast('反馈类型已存在','error');state.settings.feedbackTypes=[...feedbackTypes(),name];save('反馈类型已添加');feedbackTypeSettings()}
function deleteFeedbackType(name){const used=state.feedback.filter(f=>f.type===name).length;if(used)return toast(`已有 ${used} 条反馈使用"${name}"，请先迁移反馈`,'error');state.settings.feedbackTypes=feedbackTypes().filter(x=>x!==name);save('反馈类型已删除');feedbackTypeSettings()}
function feedbackForm(f={}){modalState={type:'feedback',id:f.id};modal('新增客户反馈',`<form id="feedbackForm" class="zx-form-grid"><div class="zx-field"><label>关联客户 ${requiredMark}</label><select class="zx-select" name="customerId" required><option value="">请选择客户</option>${officialCustomers().map(c=>`<option value="${c.id}" ${String(f.customerId)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="zx-field"><label>反馈类型</label><select class="zx-select" name="type">${feedbackTypes().map(x=>`<option ${f.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="zx-field"><label>优先级</label><select class="zx-select" name="priority"><option>普通</option><option>中</option><option>高</option></select></div><div class="zx-field"><label>截止日期</label><input class="zx-input" type="date" name="dueDate"></div><div class="zx-field full"><label>反馈内容 ${requiredMark}</label><textarea class="zx-textarea" name="content" required></textarea></div></form>`,`<button class="zx-btn" data-action="close-modal">取消</button><button class="zx-btn primary" data-action="save-feedback">保存反馈</button>`)}
function beginStatusSettingsEdit(){if(statusSettingsBaseline)return;statusSettingsBaseline={statuses:cloneData(state.statuses||[]),priorityConfig:cloneData(state.settings.priorityConfig||{})}}
function restoreStatusSettingsBaseline(){if(!statusSettingsBaseline)return;state.statuses=cloneData(statusSettingsBaseline.statuses);state.settings.priorityConfig=cloneData(statusSettingsBaseline.priorityConfig)}
function refreshStatusSettingsBaseline(){statusSettingsBaseline={statuses:cloneData(state.statuses||[]),priorityConfig:cloneData(state.settings.priorityConfig||{})}}
function statusPriorityDefaults(status){const fallback=localPriorityRule(status?.name);return{enabled:status?.priority_enabled==null?!fallback.excluded:Boolean(status.priority_enabled),score:status?.priority_score==null?fallback.score:Math.max(0,Math.min(100,Number(status.priority_score)||0)),excluded:status?.priority_excluded==null?fallback.excluded:Boolean(status.priority_excluded)}}
function statusPriorityFields(status){const p=statusPriorityDefaults(status);return `<div class="zx-status-priority-fields"><label><input type="checkbox" data-status-priority-enabled="${attr(status.id)}" ${p.enabled?'checked':''}>参与评分</label><label>分值 <input class="zx-input zx-status-priority-score" type="number" min="0" max="100" step="1" value="${p.score}" data-status-priority-score="${attr(status.id)}"></label><label><input type="checkbox" data-status-priority-excluded="${attr(status.id)}" ${p.excluded?'checked':''}>排除</label></div>`}
async function persistSalesStatusConfigs(){if(!syncState.ready)throw new Error('团队同步尚未准备好，请稍后再试');const statuses=(state.statuses||[]).map((status,index)=>({...status,sort_order:index,priority_enabled:status.priority_enabled==null?statusPriorityDefaults(status).enabled:status.priority_enabled,priority_score:status.priority_score==null?statusPriorityDefaults(status).score:status.priority_score,priority_excluded:status.priority_excluded==null?statusPriorityDefaults(status).excluded:status.priority_excluded}));await syncFetch('/api/sales-statuses',{method:'PUT',headers:{'Content-Type':'application/json','X-Request-Id':requestId()},body:JSON.stringify({statuses,priorityConfig:getPriorityConfig()})});const snapshot=await syncFetch('/api/sync/snapshot');if(!snapshot?.state)throw new Error('销售状态已写入，但未能读取最新服务器数据');applyIncomingSnapshot(snapshot);return snapshot}
function managedWechatAccountSettings(){const accounts=managedWechatAccounts();return `<section class="zx-custom-settings-section"><h3>管理微信账户</h3><div class="zx-toolbar"><input class="zx-input" id="newManagedWechatAccountName" maxlength="50" placeholder="新增管理微信账户"><button class="zx-btn primary" data-action="add-managed-wechat-account">添加</button></div><div class="zx-list">${accounts.length?accounts.map(name=>{const used=state.customers.filter(c=>managedWechatAccountMatches(c,name)).length;return `<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title"><span data-managed-wechat-account-name="${attr(name)}">${esc(name)}</span><input class="zx-input" data-edit-managed-wechat-account-input="${attr(name)}" value="${attr(name)}" style="display:none;max-width:220px"></div><div class="zx-list-meta">${used} 位客户正在使用</div></div><div class="zx-list-actions"><button class="zx-btn small" data-edit-managed-wechat-account="${attr(name)}">编辑</button><button class="zx-btn danger small" data-delete-managed-wechat-account="${attr(name)}">删除</button></div></div>`}).join(''):'<div class="zx-empty">暂无自定义管理微信账户，客户默认归入“未分配”。</div>'}</div></section>`}
function addManagedWechatAccount(){const input=$('#newManagedWechatAccountName'),name=normalizeManagedWechatAccount(input?.value);if(!name)return toast('请输入管理微信账户名称','error');if(name==='未分配')return toast('“未分配”是系统保留选项，不能作为自定义账户名','error');if(managedWechatAccounts().includes(name))return toast('管理微信账户已存在','error');state.settings.managedWechatAccounts=[...managedWechatAccounts(),name];save('管理微信账户已添加');customSettings()}
function renameManagedWechatAccount(oldName,newName){newName=normalizeManagedWechatAccount(newName);if(!newName)return toast('请输入管理微信账户名称','error');if(newName==='未分配')return toast('“未分配”是系统保留选项，不能重命名为该名称','error');if(newName!==oldName&&managedWechatAccounts().includes(newName))return toast('管理微信账户已存在','error');state.settings.managedWechatAccounts=managedWechatAccounts().map(name=>name===oldName?newName:name);state.customers.forEach(c=>{const accounts=normalizeManagedWechatAccounts(c).map(name=>name===oldName?newName:name);c.managed_wechat_accounts=[...new Set(accounts)];c.managed_wechat_account=c.managed_wechat_accounts[0]||''});save('管理微信账户已更新');customSettings()}
function deleteManagedWechatAccount(name){const used=state.customers.filter(c=>managedWechatAccountMatches(c,name)).length;if(used)return toast(`已有 ${used} 位客户正在使用“${name}”，请先调整客户`,'error');state.settings.managedWechatAccounts=managedWechatAccounts().filter(item=>item!==name);save('管理微信账户已删除');customSettings()}
function customSettings(){beginStatusSettingsEdit();modalState={type:'custom-settings'};const identities=state.settings.identities||DEFAULT_IDENTITIES;modal('自定义',`<div class="zx-custom-settings"><section class="zx-custom-settings-section"><h3>客户身份</h3><div class="zx-toolbar"><input class="zx-input" id="newIdentityName" placeholder="新增客户身份"><button class="zx-btn primary" data-action="add-identity">添加</button></div><div class="zx-list">${identities.map(x=>`<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(x)}</div><div class="zx-list-meta">${state.customers.filter(c=>c.identity===x).length} 位客户正在使用</div></div><button class="zx-btn danger small" data-delete-identity="${attr(x)}">删除</button></div>`).join('')}</div></section><section class="zx-custom-settings-section"><h3>销售状态</h3><div class="zx-list" id="statusRows">${state.statuses.map(s=>`<div class="zx-list-item zx-status-setting-row"><input type="color" value="${s.color}" data-status-color="${s.id}"><div class="zx-list-main"><input class="zx-input" value="${attr(s.name)}" data-status-name="${s.id}">${statusPriorityFields(s)}</div><button class="zx-btn danger small" data-delete-status="${s.id}">删除</button></div>`).join('')}</div><div class="zx-actions" style="margin-top:15px"><input class="zx-input" id="newStatusName" placeholder="新状态名称"><input type="color" id="newStatusColor" value="#315efb"><button class="zx-btn" data-action="add-status">添加</button></div></section>${managedWechatAccountSettings()}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button><button class="zx-btn primary" data-action="save-statuses">保存设置</button>`,true)}
function identitySettings(){modalState={type:'identities'};const items=state.settings.identities||DEFAULT_IDENTITIES;modal('客户身份配置',`<div class="zx-alert">客户身份配置位于客户管理页面。已有客户正在使用的身份不能直接删除，可先停用或迁移。</div><div class="zx-toolbar"><input class="zx-input" id="newIdentityName" placeholder="新增客户身份"><button class="zx-btn primary" data-action="add-identity">添加</button></div><div class="zx-list">${items.map((x,i)=>`<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(x)}</div><div class="zx-list-meta">${state.customers.filter(c=>c.identity===x).length} 位客户正在使用</div></div><button class="zx-btn danger small" data-delete-identity="'+attr(x)+'">删除</button></div>`).join('')}</div>`,`<button class="zx-btn" data-action="close-modal">关闭</button>`,true)}
const _priorityStatusSettings=priorityStatusSettings;priorityStatusSettings=function(){beginStatusSettingsEdit();return _priorityStatusSettings.apply(this,arguments)};
const _statusSettings=statusSettings;statusSettings=function(){beginStatusSettingsEdit();return _statusSettings.apply(this,arguments)};
function addIdentity(){const input=$('#newIdentityName'),name=input?.value.trim();if(!name)return toast('请输入身份名称','error');if(!state.settings.identities.includes(name))state.settings.identities.push(name);save('客户身份已添加');modalState?.type==='custom-settings'?customSettings():identitySettings()}
function deleteIdentity(name){const using=state.customers.filter(c=>c.identity===name).length;if(using)return toast(`已有 ${using} 位客户使用该身份，请先迁移客户`,'error');state.settings.identities=state.settings.identities.filter(x=>x!==name);save('客户身份已删除');modalState?.type==='custom-settings'?customSettings():identitySettings()}
function priorityStatusSettings(){modalState={type:'priority-status-settings'};const config=getPriorityConfig(),w=config.weights,fBudget=w.followers,eBudget=w.evidence,sBudget=w.status;const weightBar='<div class="zx-priority-weight-bar"><div class="zx-priority-weight-input"><label>粉丝量</label><input class="zx-input zx-priority-weight-followers" type="number" min="0" max="100" step="1" value="'+w.followers+'" data-weight="followers"><span>%</span></div><div class="zx-priority-weight-input"><label>朋友圈客单是否达标</label><input class="zx-input zx-priority-weight-evidence" type="number" min="0" max="100" step="1" value="'+w.evidence+'" data-weight="evidence"><span>%</span></div><div class="zx-priority-weight-input"><label>销售状态</label><input class="zx-input zx-priority-weight-status" type="number" min="0" max="100" step="1" value="'+w.status+'" data-weight="status"><span>%</span></div><div class="zx-priority-weight-sum is-valid"><span id="priorityWeightSum">合计 '+priorityWeightTotal(w)+'</span><button type="button" class="zx-btn small zx-priority-weight-save" data-action="save-priority-weights">保存</button></div></div>';const followerRows=(config.followers||[]).map((t,i)=>'<div class="zx-priority-settings-row"><span class="zx-priority-settings-name"><strong>粉丝量 ≥ '+attr(String(t.min))+'</strong></span><label class="zx-priority-setting-score">阈值 <input class="zx-input zx-priority-follower-min" type="number" min="0" step="100" value="'+t.min+'" data-follower-index="'+i+'"></label><label class="zx-priority-setting-score">分值 <input class="zx-input zx-priority-follower-score" type="number" min="0" max="'+fBudget+'" step="1" value="'+Math.min(t.score,fBudget)+'" data-follower-index="'+i+'"></label></div>').join('');const evidenceRows=(config.evidence||[]).map((t,i)=>'<div class="zx-priority-settings-row"><span class="zx-priority-settings-name"><strong>朋友圈客单是否≥ '+attr(String(t.min))+' 张</strong></span><label class="zx-priority-setting-score">阈值 <input class="zx-input zx-priority-evidence-min" type="number" min="0" step="1" value="'+t.min+'" data-evidence-index="'+i+'"></label><label class="zx-priority-setting-score">分值 <input class="zx-input zx-priority-evidence-score" type="number" min="0" max="'+eBudget+'" step="1" value="'+Math.min(t.score,eBudget)+'" data-evidence-index="'+i+'"></label></div>').join('');modal('自定义评估分值占比和梯队','<div class="zx-alert">总分为 100 分，先设置三大维度的分值占比（%），再分别配置每个维度内的具体分值。配置会同步到团队并联动评分计算。</div><section class="zx-priority-config-section zx-priority-weight-section"><h3>三大维度分值占比（%）</h3>'+weightBar+'</section><section class="zx-priority-config-section"><h3>梯队分值界限</h3><div class="zx-priority-settings-list"><div class="zx-priority-settings-row"><span class="zx-priority-settings-name"><strong>第一梯队</strong><span class="zx-list-meta">≥</span></span><label class="zx-priority-setting-score">分值界限 <input class="zx-input zx-priority-threshold-first" type="number" min="1" max="99" step="1" value="'+config.thresholds.first+'"></label><span class="zx-priority-setting-hint">分及以上</span></div><div class="zx-priority-settings-row"><span class="zx-priority-settings-name"><strong>第二梯队</strong><span class="zx-list-meta">≥</span></span><label class="zx-priority-setting-score">分值界限 <input class="zx-input zx-priority-threshold-second" type="number" min="1" max="99" step="1" value="'+config.thresholds.second+'"></label><span class="zx-priority-setting-hint">分及以上</span></div><div class="zx-priority-settings-row"><span class="zx-priority-settings-name"><strong>第三梯队</strong><span class="zx-list-meta">≥</span></span><label class="zx-priority-setting-score">分值界限 <input class="zx-input zx-priority-threshold-third" type="number" min="1" max="99" step="1" value="'+config.thresholds.third+'"></label><span class="zx-priority-setting-hint">分及以上</span></div></div></section><section class="zx-priority-config-section"><h3 data-priority-budget="followers">粉丝量分值（满分 '+fBudget+' 分）</h3><div class="zx-priority-settings-list">'+followerRows+'</div></section><section class="zx-priority-config-section"><h3 data-priority-budget="evidence">朋友圈客单是否达标（满分 '+eBudget+' 分）</h3><div class="zx-priority-settings-list">'+evidenceRows+'</div></section><section class="zx-priority-config-section"><h3 data-priority-budget="status">销售状态优先级（满分 '+sBudget+' 分）</h3><div class="zx-priority-settings-list">'+state.statuses.map(status=>{const p=statusPriorityDefaults(status);return '<div class="zx-priority-settings-row"><div class="zx-priority-settings-name"><span class="zx-status-color-dot" style="background:'+attr(status.color||'#315efb')+'"></span><strong>'+esc(status.name)+'</strong></div><label class="zx-priority-setting-check"><input type="checkbox" data-status-priority-enabled="'+attr(status.id)+'" '+(p.enabled?'checked':'')+'>参与评分</label><label class="zx-priority-setting-score">分值 <input class="zx-input zx-status-priority-score" type="number" min="0" max="'+sBudget+'" step="1" value="'+Math.min(p.score,sBudget)+'" data-status-priority-score="'+attr(status.id)+'"></label><label class="zx-priority-setting-check"><input type="checkbox" data-status-priority-excluded="'+attr(status.id)+'" '+(p.excluded?'checked':'')+'>排除</label></div>'}).join('')+'</div></section>','<button class="zx-btn" data-action="close-modal">取消</button><button class="zx-btn primary" data-action="save-statuses">保存并同步</button>',true)}
