function highlightText(value,term){const safe=esc(value||'');const q=String(term||'').trim();if(!q)return safe;const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');return safe.replace(re,m=>`<mark class="zx-chat-highlight">${m}</mark>`)}
function customerPrioritySummary(c){const evidenceCount=customerEvidenceState.get(String(c.id))?.count||0;const config=getPriorityConfig(),threshold=getEvidenceQualificationThreshold(config),qualified=getMomentsOrderQualified(c,evidenceCount,config);const followers=localFollowers(c.douyin_followers),fp=computeFollowerScore(followers),ep=computeEvidenceScore(qualified,config),rule=localPriorityRule(c.sales_status,(state.statuses||[]).find(status=>status.name===c.sales_status)),score=fp+ep+rule.score,ladder=getTierLabel(score);return `<section class="zx-customer-priority-panel"><div class="zx-customer-priority-head"><div><strong>优先对接评分</strong><small>${esc(ladder)}</small></div><b>${score} 分</b></div><div class="zx-customer-priority-breakdown"><span>粉丝量 +${fp}</span><span>朋友圈客单是否≥ ${threshold} 张：${momentsQualificationText(qualified)} +${ep}</span><span>销售状态 +${rule.score}</span></div></section>`}
function renderCustomerEvidencePanel(c){const data=customerEvidenceState.get(String(c.id))||{count:0,items:[],loading:false};const manualCount=Number(c.moments_orders)||0;const totalCount=data.count+manualCount;const threshold=getEvidenceQualificationThreshold();const qualified=getMomentsOrderQualified(c,data.count);const manualNote=manualCount>0?`（其中手动录入 ${manualCount} 张）`:'';return `<section class="zx-customer-evidence-panel"><div class="zx-customer-evidence-head"><div><strong>朋友圈客单截图</strong><small>${totalCount?`已录入 ${totalCount} 张${manualNote}`:'未录入'} · 是否≥ ${threshold} 张：${momentsQualificationText(qualified)}</small></div><label class="zx-btn small" for="customerEvidenceUpload">上传截图</label><input id="customerEvidenceUpload" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden></div>${data.loading?'<div class="zx-empty">正在读取截图…</div>':data.items?.length?`<div class="zx-customer-evidence-grid">${data.items.map(item=>`<figure><img src="${attr(item.fileUrl)}" alt="${attr(item.fileName)}" loading="lazy"><figcaption><span>${esc(item.fileName)}</span><button type="button" class="zx-btn ghost small" data-delete-customer-evidence="${attr(item.id)}" data-customer-id="${attr(c.id)}">删除</button></figcaption></figure>`).join('')}</div>`:'<div class="zx-empty">暂无朋友圈客单量，上传后将自动参与优先对接评分。</div>'}</section>`}
async function loadCustomerEvidence(id){try{const data=await syncFetch(`/api/customers/${encodeURIComponent(id)}/evidence`);customerEvidenceState.set(String(id),data);if(modalState?.type==='customer-detail'&&String(modalState.id)===String(id))customerDetail(id,detailTab,true)}catch(error){customerEvidenceState.set(String(id),{count:0,items:[],error:error.message})}}
async function uploadCustomerEvidence(id,files){const list=[...(files||[])];if(!list.length)return;for(const file of list){if(file.size>8*1024*1024)return toast('单张截图不能超过 8MB','error');if(!/^image\/(png|jpeg|webp|gif)$/i.test(file.type))return toast('仅支持 PNG、JPG、WEBP、GIF 图片','error')}try{for(const file of list){const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await syncFetch(`/api/customers/${encodeURIComponent(id)}/evidence`,{method:'POST',headers:{'Content-Type':'application/json','X-Request-Id':requestId()},body:JSON.stringify({fileName:file.name,dataUrl,requestId:requestId()})})}toast('朋友圈客单量已上传','success');await loadCustomerEvidence(id);loadPriorityCustomers(true)}catch(error){toast(error.message||'截图上传失败','error')}}
async function deleteCustomerEvidence(id,evidenceId){if(!confirm('确定删除这张朋友圈客单量吗？删除后仅做软删除，不会删除原客户数据。'))return;try{await syncFetch(`/api/customers/${encodeURIComponent(id)}/evidence/${encodeURIComponent(evidenceId)}`,{method:'DELETE',headers:{'X-Request-Id':requestId()}});toast('截图已删除','success');await loadCustomerEvidence(id);loadPriorityCustomers(true)}catch(error){toast(error.message||'截图删除失败','error')}}
