 if(tab==='history')content=`<div class="zx-timeline">${[...(c.statusHistory||[])].reverse().map(h=>`<div class="zx-time-item"><b>${esc(h.from||'-')} → ${esc(h.to)}</b><small>${fmt(h.at)} · ${esc(h.user||'')}</small><p>${esc(h.reason||'销售状态变更')}</p></div>`).join('')||'<div class="zx-empty">暂无状态变更记录</div>'}</div>`;
