function importRecognitionDetailsMarkup(summary,normalized){
 const sheets=summary||[];
 const recognizedKeys=new Set(sheets.flatMap(item=>item.mappedFieldKeys||[]));
 const unmappedCount=sheets.reduce((total,item)=>total+(item.unmappedHeaders||[]).length,0);
 const dataRows=sheets.reduce((total,item)=>total+Number(item.dataRowCount||0),0);
 const sheetDetails=sheets.map(item=>{
  const range=item.dataStartRow&&item.dataEndRow
   ? '第 '+item.dataStartRow+'-'+item.dataEndRow+' 行（'+(item.dataRowCount||0)+' 行数据）'
   : '未识别到数据行';
  const mappings=(item.mappings||[]).map(mapping=>
   '<span class="zx-import-recognition-map"><b>'+esc(mapping.column||'未命名列')+'</b><i>→</i>'+esc(mapping.field||'未命名字段')+'<small>'+esc(mapping.source||'')+'</small></span>'
  ).join('');
  const unmapped=(item.unmappedHeaders||[]).map(header=>
   '<span class="zx-import-recognition-unmapped">'+esc(header)+'</span>'
  ).join('');
  const header=item.headerRow
   ? '表头：第 '+item.headerRow+' 行'
   : '未检测到独立表头';
  return '<section class="zx-import-sheet-detail">'
   +'<div class="zx-import-sheet-detail-head"><strong>'+esc(item.sheet||'未命名 Sheet')+'</strong><span>'
   +header+' · 数据：'+range+'</span></div>'
   +'<div class="zx-import-recognition-group"><label>Excel 列名 → 客户字段</label><div class="zx-import-recognition-map-list">'
   +(mappings||'<span class="zx-list-meta">暂无已识别字段</span>')+'</div></div>'
   +'<div class="zx-import-recognition-group"><label>未识别列</label><div class="zx-import-recognition-unmapped-list">'
   +(unmapped||'<span class="zx-list-meta">无</span>')+'</div><small>未识别列不会丢失，会按“列名：内容”追加到对应客户的备注。</small></div></section>';
 }).join('');
 return '<section class="zx-import-recognition-panel"><div class="zx-import-recognition-stats">'
  +'<div><b>'+sheets.length+'</b><span>Sheet</span></div>'
  +'<div><b>'+(dataRows||normalized.length)+'</b><span>数据行</span></div>'
  +'<div><b>'+recognizedKeys.size+'</b><span>识别字段</span></div>'
  +'<div><b>'+unmappedCount+'</b><span>未识别列</span></div>'
  +'</div><details class="zx-import-recognition-details"><summary>查看每个 Sheet 的识别详情</summary><div class="zx-import-sheet-details">'
  +(sheetDetails||'<span class="zx-list-meta">暂无识别结果</span>')+'</div></details></section>';
}
