function readWorkbook(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{try{if(!window.XLSX)throw new Error('表格组件未加载');const wb=XLSX.read(reader.result,{type:'array',cellText:true,raw:false});const ws=wb.Sheets[wb.SheetNames[0]];resolve(XLSX.utils.sheet_to_json(ws,{defval:'',raw:false}))}catch(e){reject(e)}};reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsArrayBuffer(file)})}
function collectSheetHyperlinks(ws){const links={};if(!ws?.['!ref'])return links;const range=XLSX.utils.decode_range(ws['!ref']);for(let r=range.s.r;r<=range.e.r;r++)for(let c=range.s.c;c<=range.e.c;c++){const target=ws[XLSX.utils.encode_cell({r,c})]?.l?.Target;if(target)links[`${r}:${c}`]=String(target)}return links}function readWorkbookSheets(file,onProgress=()=>{}){return new Promise(async(resolve,reject)=>{if(typeof Worker==='undefined')return reject(new Error('当前浏览器不支持后台解析 Excel，请升级浏览器后重试'));let worker;try{onProgress(8,'正在读取 Excel 文件');const buffer=await file.arrayBuffer();worker=new Worker('./customer-import-worker.js?v=20260827-001');worker.onmessage=event=>{const message=event.data||{};if(message.type==='progress'){onProgress(message.progress,message.phase);return}worker.terminate();if(message.type==='complete')resolve(message.sheets||[]);else reject(new Error(message.message||'Excel 解析失败'))};worker.onerror=event=>{worker.terminate();reject(new Error(event.message||'Excel 后台解析失败'))};worker.postMessage({buffer,fileName:file.name||''},[buffer])}catch(error){worker?.terminate();reject(error)}})}
async function parseChatFile(e){const file=e.target.files[0];if(!file)return;$('#chatFileName').textContent=file.name;if(/^image\//.test(file.type)){const reader=new FileReader();reader.onload=()=>{modalState.screenshotImage=reader.result;modalState.fileName=file.name;const img=$('#chatScreenshotImg');if(img){img.src=reader.result;$('#chatScreenshotPreview').style.display='block';$('#chatScreenshotEditor').style.display='none'};$('#chatPreview').innerHTML='<div class="zx-chat-image-preview"><img src="'+reader.result+'" style="max-width:100%;max-height:320px;border-radius:8px;border:1px solid #e0e6f2" alt="'+esc(file.name)+'"><p style="color:#78859a;margin-top:6px;font-size:12px">'+esc(file.name)+' · 图片已加载，可编辑或直接保存</p></div>';toast('图片已加载，可编辑或直接保存')};reader.readAsDataURL(file);return}try{let messages=[];if(/\.xlsx?$/.test(file.name.toLowerCase())){const rows=await readWorkbook(file);messages=rows.map((r,i)=>({sender:r['发送人']||r['姓名']||'',time:r['时间']||'',content:r['内容']||Object.values(r).join(' ')})).filter(x=>x.content)}else{const text=await file.text();messages=text.split(/\r?\n/).filter(Boolean).map((line,i)=>{const m=line.match(/^\[?([^\]]*\d{1,2}:\d{2}[^\]]*)\]?\s*([^:：]{1,30})[:：]\s*(.*)$/);return m?{time:m[1],sender:m[2],content:m[3]}:{time:'',sender:'',content:line}})}modalState.messages=messages;modalState.fileName=file.name;$('#chatPreview').innerHTML=`<div class="zx-alert">已解析 ${messages.length} 条记录</div><div class="zx-preview"><div class="zx-list" style="padding:0 14px">${messages.slice(0,30).map(m=>`<div class="zx-list-item"><div class="zx-list-main"><div class="zx-list-title">${esc(m.sender||'消息')}</div><div class="zx-list-meta">${esc(m.time||'')}</div><p style="margin:5px 0">${esc(m.content)}</p></div></div>`).join('')}</div></div>`}catch(err){toast(err.message,'error')}}
