  const infoFields=[['姓名',c.name],['销售状态',c.sales_status],['省份',c.province],['城市',c.city],['手机号',c.phone],['客户身份',c.identity],['机构名称',c.org_name],['微信昵称',c.wechat_nickname],['微信号',c.wechat_id],['QQ号',c.qq],['抖音昵称',c.douyin_nickname],['抖音号',c.douyin_id],['抖音粉丝量',c.douyin_followers],['朋友圈客单',c.moments_orders],['视频号',c.channel_account],['公众号',c.official_account],['地址',c.address],['备注',c.remark]];
