  classifyDeletionJobFromSnapshot(job,snapshot);applyIncomingSnapshot(snapshot,{backgroundBatch:true,authoritativeBatch:job});
  if(customerById(pendingId))throw new Error(job.statusChangedIds.includes(String(pendingId))?'该客户状态已发生变化，未能按待确认客户删除':'后端未确认删除该待确认客户，请刷新后重试');
