const syncNoticeSeen=new Set();
const syncOperationLabels={patch:'数据修改',backup:'备份导入',fullBackupRestore:'备份恢复',import:'批量导入',directImport:'批量导入并加入客户库',safeReplacementPending:'可安全替换客户加入待确认客户',promote:'批量加入客户库',capturePromote:'客户采集加入客户库',delete:'批量删除客户',captureDelete:'批量删除客户采集',replace:'批量替换客户'};
