 source.onmessage=handle;
 ['workspace.updated','workspace.initialized','workspace.import.completed','customer.created','customer.updated','customer.approved','customer.deleted','customer.status_changed','customer.merged','customer.capture_created','customer.capture_confirmed','customer.priority_changed','customer.evidence_added','customer.evidence_deleted','priority_config.updated','task.created','task.updated','task.completed','task.reopened','task.deleted','feedback.created','feedback.updated','feedback.status_changed','feedback.deleted','chat_record.created','chat_record.deleted','sales_status.created','sales_status.updated','sales_status.deleted','settings.updated','knowledge.created','knowledge.updated','knowledge.deleted','knowledge.relations_updated','knowledge.relation_deleted','customer.permission_requested','customer.permission_approved','customer.permission_rejected','customer.permission_revoked','workspace.business_data_cleared','sync.operation.accepted','sync.operation.progress','sync.operation.retrying','sync.operation.completed','sync.operation.failed'].forEach(name=>source.addEventListener(name,handle));
 source.onopen=()=>{syncState.realtimeDisconnected=false;if(!hasSyncWork())clearSyncRetryNotice();};
